INSERT INTO news_item (
    id, tenant_id, category_id, slug, title, summary, status, author_name,
    featured, priority, estimated_read_minutes, published_at, created_at, updated_at
)
VALUES
    ('news-item-e83a8d28c135ba5d', '100001', 'news-category-finance-flash', 'em-202611273941224319-21e3684e0c', '人民日报刊文：别把“豆包”当医生', '如今，越来越多的患者到医院看病，都要问问“豆包”等AI(人工智能)通用大模型。据悉，仅“豆包”每天的健康咨询量就超过2000万人次。AI已经成为医患之间的“第三方力量”，并对患者的医疗决策产生实际影响。传统的医患双方诊疗模式，正在变成“患者—医生—AI”三方博弈模式。当AI的答案与医生的结论不一致时，有的患者便会质疑医生，无形中增加了医患沟通成本。', 'published', NULL, FALSE, 100, 1, '2026-11-26T23:58:53Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-30d5b4f1220fcd2b', '100001', 'news-category-finance-flash', 'em-202611273941029848-81d41417c2', '超强厄尔尼诺带来多重风险', '世界气象组织（WMO）日前发布的公报表示，厄尔尼诺现象已确定形成并迅速增强，预计12月达到峰值，持续至2027年2月的可能性接近100%，可能成为至少自1950年以来最强的厄尔尼诺之一。受其影响，全球大部分地区气温可能高于平均水平，降雨模式将发生改变，一些地区发生干旱和洪水的风险增加。', 'published', NULL, FALSE, 100, 1, '2026-11-26T23:57:01Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-79cf8487c6811d9d', '100001', 'news-category-finance-flash', 'em-202611273941213015-8437dbf5f2', '美国GDP大幅上调 特朗普猛批“误导选民”：为什么中期选举前不早说？', '美国总统特朗普星期四呼吁对例行修正的经济增长数据展开调查，借此继续兜售他关于美国中期选举遭到干预的无端指控。此前一天，美国商务部将第三季度国内生产总值（GDP）增速从此前预估的3.4%大幅上调至4.3%。尽管此类数据修订在经济统计中十分常见，但特朗普仍对他口中的“虚假”数据猛烈抨击。', 'published', NULL, FALSE, 100, 1, '2026-11-26T23:56:08Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-df8ca30c7a6f7c90', '100001', 'news-category-finance-flash', 'em-202611273941029928-89d0f8e72f', '全球软商品市场受扰动', '厄尔尼诺事件带来的影响已在软商品市场显现。食糖作为代表性品种，本轮行情具备很强样本意义：8月至10月中旬，国际原糖期货和A股食糖板块一起走强；11月以来，受主产国开榨加快、投资资金减仓等因素影响，国际糖价从高位有所回调；截至11月下旬，ICE原糖期货回落至18美分/磅左右，国内郑糖主力合约在5100元/吨一线震荡，市场重心从“炒预期”转向“看实产”。', 'published', NULL, FALSE, 100, 1, '2026-11-26T23:56:01Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-ccf22d8b458a12df', '100001', 'news-category-finance-flash', 'em-202611273941030398-b3a2d6cd56', '全球黄金储备迁移进程加速', '黄金“回家”正在全球金库之间悄然进行。从新德里到法兰克福，从巴黎到伊斯坦布尔，从华沙到阿姆斯特丹，越来越多的国家正从纽约和伦敦撤回黄金储备，转移至本国或更可控的司法管辖区。2026年，在制裁风险、贸易冲突以及对西方金融体系信任度下降的背景下，黄金储备转移进程明显加快，这不是恐慌性抛售，而是对危机时刻本国黄金“控制权”的重新架构。', 'published', NULL, FALSE, 100, 1, '2026-11-26T23:55:01Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-00f0d46106ffbb09', '100001', 'news-category-finance-flash', 'em-202611273941194885-9f2a499ca1', 'MiniMax创始人：加快采用华为和阿里AI芯片 减少对英伟达依赖', '11月26日，据The Information，一名参加MiniMax全员会的员工透露，11月20日，MiniMax创始人兼CEO闫俊杰在会上表示，公司将加快采用华为和阿里巴巴的AI芯片，以减少对英伟达的依赖。', 'published', NULL, FALSE, 100, 1, '2026-11-26T23:53:29Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-5f332abc4900a4d2', '100001', 'news-category-finance-flash', 'em-202611273941197769-d9159da279', '日本至11月20日当周外资买进日债2085亿日元 前值6501亿日元', '日本至11月20日当周外资买进日债2085亿日元，前值6501亿日元。', 'published', NULL, FALSE, 100, 1, '2026-11-26T23:51:55Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-aa1bf7c1e1f33211', '100001', 'news-category-finance-flash', 'em-202611273941196565-7dd5ab4c23', '日本至11月20日当周外资买进日股-5716亿日元 前值-2241亿日元', '日本至11月20日当周外资买进日股-5716亿日元，前值-2241亿日元。', 'published', NULL, FALSE, 100, 1, '2026-11-26T23:51:35Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-dd6814443f9d6c3f', '100001', 'news-category-finance-flash', 'em-202611273941012918-17130723e9', '不拼硬件拼生态 AI手机市场“升温”', '近期，继第二代“豆包手机”之后，华为等头部厂商相继入局AI手机赛道。受访专家认为，在AI手机这条新赛道上，单凭硬件参数已难以形成竞争优势，市场将转向操作系统、大模型与应用生态的系统性比拼。', 'published', NULL, FALSE, 100, 1, '2026-11-26T23:51:05Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-7139e6dffb0de4cd', '100001', 'news-category-finance-flash', 'em-202611273941013212-21dff75900', '金融活水润泽乌兰察布算力产业“水丰草美”', '作为内蒙古算力产业核心区域，乌兰察布依托风光资源与区位禀赋加速布局算力产业集群。记者日前在乌兰察布采访时了解到，通过多项资本工具的协同联动，金融机构已经构建起覆盖项目全生命周期的服务体系，助力乌兰察布实现从“草原云谷”到“Token之都”的产业蝶变。', 'published', NULL, FALSE, 100, 1, '2026-11-26T23:49:07Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-40c973def5a20cc2', '100001', 'news-category-finance-flash', 'em-202611273941176425-3fe3eaea1d', '30只深度回调股年内大手笔回购且高股息率', '近期，股市大幅震荡，上市公司积极出手，维护公司价值。据证券时报·数据宝统计，今年以来（截至11月26日），不包括股权激励注销类回购，上市公司累计发布回购预案超过870份（公司不去重），公告回购金额上限近2700亿元，下限近1500亿元。', 'published', NULL, FALSE, 100, 1, '2026-11-26T23:49:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-57d7f59269357b17', '100001', 'news-category-finance-flash', 'em-202611273941168554-d5220b7dc8', '日经225指数期货早盘上涨0.8%', '日经225指数期货早盘上涨0.8%。', 'published', NULL, FALSE, 100, 1, '2026-11-26T23:46:45Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-0314e4b6bc185a91', '100001', 'news-category-finance-flash', 'em-202611273941006265-619f9a546c', '风电行业投资投产加快产能布局', '近期，风电产业链多个环节接连传出投资、投产消息，覆盖风电场开发、叶片材料、核心铸件等多个领域。在需求恢复与行业竞争格局调整的背景下，风电产业链企业正通过产能建设、产品升级等方式谋求新的发展空间。', 'published', NULL, FALSE, 100, 1, '2026-11-26T23:46:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-a74ecfa787ad6b16', '100001', 'news-category-finance-flash', 'em-202611273941155789-bcb5adab1a', '鸿合科技：采取包括产业并购等多种方式推动业务落地', '鸿合科技在投资者关系活动中表示，鸿合半导体注册资本6亿元，已按照设立方案及项目节奏完成部分实缴。半导体已纳入公司三年战略规划，公司正在综合研判半导体全产业链特征，并结合公司经营现状与资源禀赋推进“智芯”业务布局。公司将持续关注产业链优质公司机会，采取包括产业并购等多种方式推动业务落地，后续如开展外延并购或产业投资，将综合评估多重因素审慎决策。', 'published', NULL, FALSE, 100, 1, '2026-11-26T23:45:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-033859d5e01f3731', '100001', 'news-category-finance-flash', 'em-202611273941010174-b3e99a28d7', '贺岁档拉开帷幕 已有57部电影定档', '灯塔专业版数据显示，截至11月26日19时，年内电影市场票房达到322.17亿元。值得一提的是，11月27日将开启时间跨度长达35天的贺岁档（11月27日至12月31日），也是今年最后一个超长档期。', 'published', NULL, FALSE, 100, 1, '2026-11-26T23:45:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-d3e7fdf225966b32', '100001', 'news-category-finance-flash', 'em-202611273941010656-5f41e1cf1f', 'AI算力建设催生需求 多家公司扩产高端电子树脂', 'AI算力建设对覆铜板材料需求的拉动，正在电子树脂环节催生一轮以高端品类为主线的扩产。11月23日晚间，道生天合材料科技（上海）股份有限公司发布公告称，拟在浙江省衢州智造新城投资建设年产8000吨高性能电子树脂项目。', 'published', NULL, FALSE, 100, 1, '2026-11-26T23:44:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-a510ec217cb19589', '100001', 'news-category-finance-flash', 'em-202611273941011340-63d33764f4', '钠电商业化落地按下“快进”键', '今年以来，钠电商业化落地的整体节奏明显加快。截至11月26日，国内一批钠离子电池示范项目集中落地，覆盖电网调峰、配网稳压等多个应用方向。与锂电池相比，钠电池的优势主要在于钠元素地壳储量丰富、低温性能优异、安全属性突出，还可在短时间内实现大功率放电。当前行业已形成普遍共识：钠电池并非替代锂电池，而是作为重要互补方案，采用“锂钠搭配”的协同模式。', 'published', NULL, FALSE, 100, 1, '2026-11-26T23:43:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-d67bb5b80675cb8b', '100001', 'news-category-finance-flash', 'em-202611273941120355-905d1afb08', '日本电力公司JERA据悉同Anthropic、Meta等科技巨头洽谈数据中心事宜', '据报道，日本最大电力生产商JERA已同Anthropic、Meta等科技巨头展开磋商，计划在东京周边地区的发电厂附近建设数据中心。报道称，JERA也正与亚马逊、微软和谷歌洽谈。', 'published', NULL, FALSE, 100, 1, '2026-11-26T23:42:11Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-b958ce333e9d5b33', '100001', 'news-category-finance-flash', 'em-202611273941141150-1e53f8604f', '荣盛发展：拟与平安信托重组本金9.29亿元债务', '11月26日，荣盛发展（002146.SZ）披露关于债务重组的公告。公告称，公司子公司蚌埠荣盛锦业房地产开发有限公司作为债务人，与平安信托存续债务本金9.29亿元、违约金及相关费用，公司子公司廊坊开发区荣盛房地产开发有限公司以其自有资产提供抵押担保，公司及子公司重庆荣乾房地产开发有限公司提供连带责任担保。', 'published', NULL, FALSE, 100, 1, '2026-11-26T23:41:49Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-61a62af26b9c4368', '100001', 'news-category-finance-flash', 'em-202611273941047268-85fbd57c90', '动力电池格局重塑 二线阵营分化明显', '中国汽车流通协会乘用车市场信息联席分会秘书长崔东树表示，2026年动力电池市场呈现“双雄份额松动，二线梯队加速崛起”的态势，国轩高科、亿纬锂能、吉利耀宁等二线企业份额显著提升，尾部企业份额基本清零，行业集中度下降、竞争更趋多元。然而，份额在重新分配，利润却未同步改善，这一落差构成当前锂电行业的主线。', 'published', NULL, FALSE, 100, 1, '2026-11-26T23:41:16Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-f25d4f2c981be9f6', '100001', 'news-category-finance-flash', 'em-202611273941045589-a4e1e24041', '智驾底座迭代提速 车企竞逐物理AI赛道', '11月25日的广州，两场发布会几乎同时开场。华南理工大学的体育馆里，小鹏人形机器人IRON被请上主持位，与台下观众和记者进行互动交流；十几公里外的蔚来科技日现场，公司CEO李斌把大半时间留给了“AI原生组织”与CBU（基本经营单元），产品发布被压到后段。一家将机器人置于台前，一家将组织变革作为主线。两家给出的展示主体不同，指向却是同一个判断：AI竞赛正从功能层下沉到底座层，再外溢到组织与产品形态。', 'published', NULL, FALSE, 100, 1, '2026-11-26T23:40:40Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-17ff53dd5f6636af', '100001', 'news-category-finance-flash', 'em-202611273941045489-55c2fc394b', '欧盟混动配额落地 中国车企出海迎规则新变量', '11月24日，欧盟委员会公布对部分进口混动乘用车实施临时保障措施。自12月1日起，欧盟将实施为期200天的进口数量配额，中国原产的相关车型获约19.18万辆额度，居各国别配额之首。商务部当天回应，希望欧方切实遵守双方共识，不折不扣落实非歧视原则，公平、公正开展调查。', 'published', NULL, FALSE, 100, 1, '2026-11-26T23:38:42Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-8a8ae88a78565d44', '100001', 'news-category-finance-flash', 'em-202611273941045257-38977d8921', '债市波动传导至表内表外 银行体系资产负债管理精细化升级', '10月末以来债市的调整，正在商业银行资产负债表的表内与表外同时留下印记。表内，债券持仓的公允价值浮亏拖累非息收入，部分中小银行此前依靠拉长久期增厚收益的配债模式遭遇考验；表外，银行理财产品净值出现回撤，预防性赎回的负反馈链条开始显现。更深层次的影响则落在资本补充环节，多家国有大行、股份制银行、地方性中小银行发债计划按下“暂停键”。', 'published', NULL, FALSE, 100, 1, '2026-11-26T23:37:44Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-6cc9471e672f186a', '100001', 'news-category-finance-flash', 'em-202611273941088843-42314c3bc3', '中信建投：国产算力供需共振 AI安全需求持续升级', '中信建投研报称，近日BIS新规将管制延伸至云端算力与制造服务，海外算力、代工、封测三通道同步收紧，国内客户采购加速转向本土。国产供应链已基本闭环。国产算力2027年起有望加速放量。AIAgent攻击频发推动安全向运行时防护升级，海外龙头加速平台化并购，国内安全板块利润拐点已现，有望受益AI安全带来的新市场需求。', 'published', NULL, FALSE, 100, 1, '2026-11-26T23:37:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-3d2b932767543f47', '100001', 'news-category-finance-flash', 'em-202611273941045837-0aed3123c9', '基金公司出招 助投资者看清主动ETF“明牌”', '首批18只主动ETF已全部挂牌上市。主动ETF须于每个交易日开市前披露基于前一交易日真实持仓的申购赎回清单（PCF），这一机制提升了基金投资的透明度，但PCF清单格式专业、数据繁杂，普通投资者直接阅读门槛较高。对此，基金公司纷纷出招，易方达基金、华夏基金等近期相继落地或优化了针对主动ETF的持仓查询与解读服务，将“每日亮牌”的监管要求转化为投资者看得清、看得懂的决策参考。', 'published', NULL, FALSE, 100, 1, '2026-11-26T23:36:52Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-c7dfa1018435064d', '100001', 'news-category-finance-flash', 'em-202611273941006331-b8d8733948', '入境消费活力加速释放 “购在中国”体验升级', '“空箱而来，满载而归”，不少海外游客在社交平台晒出在中国采购的好物，“ChinaHaul（中国购物开箱）”成为今年刷屏网络的热词。这份消费热潮的背后，是我国免签“朋友圈”的不断扩围，一系列入境便利化措施接连落地，叠加离境退税服务不断优化，多重利好合力释放了入境消费的市场潜力。境外旅客的消费体验，正在从“买得到”向“买得顺畅”加速升级，离境退税“即买即退”更是释放出远超预期的消费拉动效应。', 'published', NULL, FALSE, 100, 1, '2026-11-26T23:35:48Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-543ff643b1f2a6b9', '100001', 'news-category-finance-flash', 'em-202611273941086263-58618463cb', '中信建投：船舶行业正处于十年维度的上行景气周期', '中信建投研报称，船舶行业正处于十年维度的上行景气周期，存量运力迭代更新、环保政策趋严叠加吨海里运距拉长，为行业需求侧核心支撑逻辑。受到外部事件影响，细分船型景气分化、轮动节奏不一。当前油运运价高企，刺激油轮迎来下单潮，新船订单自2025年11月起连续高增，全年油轮订单有望维持高位；展望后市，散货船订单或将接力成为下一阶段景气主线。', 'published', NULL, FALSE, 100, 1, '2026-11-26T23:34:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-9bad9c7bbe81fd0b', '100001', 'news-category-finance-flash', 'em-202611273941072835-3752157fec', '欣旺达：控股股东提议1亿元-2亿元回购公司股份', '欣旺达11月26日晚间公告，公司控股股东、实际控制人、董事长王威提议公司使用自有资金或自筹资金（包括但不限于股票回购贷款）通过深圳证券交易所交易系统以集中竞价交易方式回购公司已发行的部分人民币普通股（A股）股票，用于注销并减少公司注册资本。回购资金总额不低于1亿元（含）且不超过2亿元（含）。', 'published', NULL, FALSE, 100, 1, '2026-11-26T23:33:41Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-14245be1574c7023', '100001', 'news-category-finance-flash', 'em-202611273941065235-e1e78db016', '中信建投：中长期角度坚定看好机器人', '中信建投研报指出，当前市场对汽车行业景气度预期仍维持低位，核心在于内需消费复苏的不确定（低基数下或依赖新一轮政策刺激）以及外需高增长能否延续（政策逆风影响），但板块行情亦完成筑底，建议重点关注结构性α，包括高业绩兑现度商用车龙头、机器人Optimus量产催化等。机器人板块短期受市场风险偏好影响显著调整，12月初特斯拉股东大会预期或有催化；中长期角度坚定看好机器人。', 'published', NULL, FALSE, 100, 1, '2026-11-26T23:33:11Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-ce9d4cc77be9b356', '100001', 'news-category-finance-flash', 'em-202611273941006565-c1e3ef1c9b', '6G产业推进提速 12只概念股获机构净买入超亿元', '6G发展正从愿景描绘转向标准研制落地，我国新一代通信网建设步入实施阶段。6G在技术验证、商业模式等方面仍有不少细节有待探索，行业共识持续凝聚。', 'published', NULL, FALSE, 100, 1, '2026-11-26T23:32:49Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-6b7bd888c1f668bc', '100001', 'news-category-finance-flash', 'em-202611273941065544-fcecca356a', '华泰证券：建议关注油气开采和具备产业链完整性的高分红龙头企业', '华泰证券研报称，考虑补库需求有望对1—2年内油价形成阶段性支撑，但中枢或逐步下移，油价长期仍存底部支撑，具备增产降本能力及天然气业务增量的高分红油气龙头企业，或将助力国内油气资源自主可控；海外炼能受损叠加库存低位，1—2年内国际成品油裂解价差中枢有望维持高位，中国能化产业链韧性较强，油价回落后伴随全球下游补库存，化纤、塑料等品类有望景气回暖。', 'published', NULL, FALSE, 100, 1, '2026-11-26T23:32:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-cb83f0589fa4090e', '100001', 'news-category-finance-flash', 'em-202611273941059245-38e576a9c7', 'A股限售股解禁一览：2.3亿元市值限售股今日解禁', '数据显示，周五（11月27日），共有9家公司限售股解禁，合计解禁量为591.49万股，按最新收盘价计算，合计解禁市值为2.3亿元。从解禁市值来看，长进光子、康希诺、芯联集成-U解禁市值居前，解禁市值分别为1.59亿元、4016.63万元、1294.13万元。', 'published', NULL, FALSE, 100, 1, '2026-11-26T23:31:40Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-db594610de707a23', '100001', 'news-category-finance-flash', 'em-202611273941006661-60f5164cb5', '高交会见证物理AI竞速落地 资本探索精准赋能硬科技', '第二十八届中国国际高新技术成果交易会11月26日在深圳开幕，5000余家海内外科创主体同台亮相，覆盖国之重器、能源、低空经济、半导体新材料、AI机器人、算力等方向，物理AI从演示走向比拼产线落地，清洁能源赛道多路线并进，一批高校孵化硬科技项目集中亮相。', 'published', NULL, FALSE, 100, 1, '2026-11-26T23:30:49Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-3dbbe685584e997b', '100001', 'news-category-finance-flash', 'em-202611273941061031-5fa36f7c37', '日本11月东京核心CPI同比增长2.9% 预期3%', '日本11月东京核心CPI同比增长2.9%，预期3%，前值2.60%。', 'published', NULL, FALSE, 100, 1, '2026-11-26T23:30:42Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-4e59c7086ca94ea9', '100001', 'news-category-finance-flash', 'em-202611273941063438-8795655b0f', '特朗普批准美国佛州重大灾害声明', '当地时间11月26日，美国总统特朗普批准佛罗里达州因本月历史性洪灾提出的重大灾害声明申请，正式启动联邦灾后援助机制，为佛州南部及中部地区受灾居民、企业和地方政府提供灾后恢复资金与资源支持。', 'published', NULL, FALSE, 100, 1, '2026-11-26T23:30:27Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-fed81f871ca2a7de', '100001', 'news-category-finance-flash', 'em-202611273941006775-5deeff36ee', '冷资源释放热效应 冰雪产业链迎发展机遇', '随着气温走低，国内“滑雪”搜索量暴涨，“冷资源”持续释放“热效应”。不少企业靠技术创新开拓市场，国产冰雪装备加速突围。', 'published', NULL, FALSE, 100, 1, '2026-11-26T23:28:49Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-ce2b8751e4969d99', '100001', 'news-category-finance-flash', 'em-202611273941049220-2974e3412f', '英国央行下调银行资本要求', '英国央行周四表示，在完成一项审查后，决定下调规模最大的本土业务型银行的资本要求。审查发现，英国本土业务占比较高的银行受到现行资本监管规则的影响尤为明显，承受的监管负担不成比例。这项改革获得英国央行金融政策委员会的支持。根据调整方案，规模最大的英国本土业务型银行的资本要求将下调60个基点，英国主要银行整体的资本要求则将下调30个基点。', 'published', NULL, FALSE, 100, 1, '2026-11-26T23:27:11Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-a4da11ede8d9cfa4', '100001', 'news-category-finance-flash', 'em-202611273941049161-60063b40f6', '德意志银行预计2027年德国股市将再创新高', '德意志银行11月26日在法兰克福举行2027年资本市场展望会议。会上发布的报告预计2027年德国经济将增长1.3%，而德国法兰克福股市DAX指数有望于2027年年底前突破28000点，再创历史新高。', 'published', NULL, FALSE, 100, 1, '2026-11-26T23:27:11Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-a411a4f0cb923020', '100001', 'news-category-finance-flash', 'em-202611273941006851-85c68b4c69', '煤电变身“调峰消防员” 脱硝改造新规酝酿中', '记者从多个独立信源处获悉，有关部门正在研究完善燃煤电厂全负荷脱硝相关技术要求，进一步加强煤电机组启停阶段的氮氧化物排放控制。多位受访者认为，煤电需要越来越灵活地响应电网调节需求，但启动阶段的环保治理又要求更加严格。未来技术升级，必须同时实现运行灵活性、设备安全性、环保合规性和经济性的协同优化。如何在合规前提下，于容量市场和辅助服务市场中实现收益最大化，成为行业高质量发展进程中的新挑战。', 'published', NULL, FALSE, 100, 1, '2026-11-26T23:26:56Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-79711be3a112834a', '100001', 'news-category-finance-flash', 'em-202611273941049028-6e7223f7bc', '中信建投信用债2027年投资策略：低利差尾声中的信用债重定价', '中信建投研报指出，2026年信用利差持续压缩，处于历史极低分位。展望2027年，从信用周期视角看，当前融资需求仍在低位，信用利差缺少趋势性走阔基础，但风险扰动项增多，市场或呈现结构性分化的行情。', 'published', NULL, FALSE, 100, 1, '2026-11-26T23:26:41Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-3f3291c4d865fd55', '100001', 'news-category-finance-flash', 'em-202611273941048977-d92182c24b', '美联储12月加息25个基点的概率为97.4%', '据CME“美联储观察”，美联储12月维持不变的概率为0.6%，加息25个基点的概率为97.4%。美联储到明年1月维持不变的概率为0.2%，累计加息25个基点的概率37%，累计加息50个基点的概率为62.7%。', 'published', NULL, FALSE, 100, 1, '2026-11-26T23:26:41Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-634d2a20a60bc61a', '100001', 'news-category-finance-flash', 'em-202611273941007969-83f7d29dba', '创业板做市商评价标准征求意见 部分交易经手费可减免', '记者获悉，深交所近日就《深圳证券交易所创业板股票做市交易业务指南（征求意见稿）》向券商征求意见。《指南》对做市商评价作出规定。根据《指南》，做市商评价包括股票做市月度评价与做市商年度综合评价。年度评价在月度评价的基础上进行，结果分为AA、A、B、C、D五档。根据评价结果，深交所对做市商进行适当的交易经手费减免和激励。据悉，目前已有20家券商在业务资格层面具备参与创业板做市的基础。', 'published', NULL, FALSE, 100, 1, '2026-11-26T23:25:36Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-425ce55273488ca7', '100001', 'news-category-finance-flash', 'em-202611273941007712-8111d5b5db', '私募机构密集发声 看好A股市场中长期投资价值', '近期市场调整，震荡加剧。在此背景下，多家私募机构密集发声，认为A股核心资产已具备长期安全边际，集体看好A股市场中长期投资价值。多和美投资、久期投资、抱朴容易等多家私募机构表示，市场风险得到释放，对A股中长期前景与回报抱有坚定信心，当前正是A股掘金的黄金时期。', 'published', NULL, FALSE, 100, 1, '2026-11-26T23:23:36Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-51cc6ae5423b4c43', '100001', 'news-category-finance-flash', 'em-202611273941048896-b661fc7dfe', '华泰证券：具身数据标准提速，关注Optimus亮相与T链', '华泰证券研报指出，上周中证机器人、中证智能汽车指数分别下跌10.69%、10.11%，跑输沪深300（-1.54%），主要受全球AI资产回调拖累。机器人方面，工信部发布5项人形机器人行业标准、具身数据国家标准启动研制，AI大厂开始用通用大模型直接控制机器人，Optimus将于12月初公开亮相。', 'published', NULL, FALSE, 100, 1, '2026-11-26T23:22:11Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-d92fceafc81f6262', '100001', 'news-category-finance-flash', 'em-202611273941048693-dc9dc3dac1', '华泰证券：地缘溢价快速回吐，需求偏弱及供应恢复或施压27年油价中枢', '华泰证券研报指出，考虑各国储备性补库需求，以及国际成品油裂解价差高位或将延续，而需求偏弱、未来供给有序恢复，以及运输紧缺缓解或将共同带动油价中枢下移，我们维持26年Brent原油期货均价预测为90美元/桶，下调27年均价预测为70美元/桶（前值77美元/桶）。', 'published', NULL, FALSE, 100, 1, '2026-11-26T23:22:10Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-d27e934f4ea249ff', '100001', 'news-category-finance-flash', 'em-202611273941005481-906335627f', '史上最大IPO四天破发意味着什么', '上市第4个交易日破发，Anthropic破发速度比SpaceX快了太多，后者撑到33天。Anthropic于11月19日登陆纳斯达克，其以813亿美元的基础募资额超越SpaceX，成为史上最大规模IPO。挂牌首日，Anthropic以111.50美元的价格开盘，较发行价高34.3%，但收盘涨幅收敛至约17%。之后公司股价连续下跌，24日收于81.905美元，跌破83美元的发行价。', 'published', NULL, FALSE, 100, 1, '2026-11-26T23:19:35Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-56e04e955132d67c', '100001', 'news-category-finance-flash', 'em-202611273941047533-6f45018521', 'AI时代靠什么升职？Anthropic高管透露绩效考核新标准', '北京时间11月27日，据《商业内幕》报道，在Anthropic，AI正在改变软件工程师的职业晋升方式。Anthropic平台工程负责人在周三发布的一档播客节目中表示，AI使得完成项目所需的时间，不再是她团队中工程师晋升条件的一个有效衡量标准，因为过去需要数年才能完成的工作现在只需数月。因此，她的团队现在越来越看重项目成果，例如降低延迟、避免事故，而不是项目耗时多久。', 'published', NULL, FALSE, 100, 1, '2026-11-26T23:18:52Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-d5af1e6357181ea0', '100001', 'news-category-finance-flash', 'em-202611273941004931-606e79599a', '航空电池走向工程验证 技术与市场仍需双向突破', '从地面到天空，动力电池企业正在寻找新的增长空间。11月以来，宁德时代接连与蓝色向量、亿维特航空两家电动垂直起降飞行器（eVTOL）企业达成独家电池合作，并与中国民航大学签约共建航空电池适航技术创新联合实验室。与此同时，11月14日，中国商飞研制的10吨级电动商用飞机CE-25A完成首次有人驾驶智能飞行。', 'published', NULL, FALSE, 100, 1, '2026-11-26T23:18:38Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-b23b5e88e87608d6', '100001', 'news-category-finance-flash', 'em-202611273941005679-71d961c2c8', '新一代通信网建设“施工图”出炉 三大细分产业驶入发展“快车道”', '11月26日，工业和信息化部、国家网信办、国家发展改革委联合印发《新一代通信网建设实施方案》，以“432”框架布局四张网、三项能力、两大支撑，明确提出以5G-A/6G、万兆光网、卫星互联网为核心支撑，将新一代通信网重新定义为经济社会运行的“神经系统”。', 'published', NULL, FALSE, 100, 1, '2026-11-26T23:17:39Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-8fb6342d68bcd46a', '100001', 'news-category-finance-flash', 'em-202611273941046915-9739772015', '总规模10亿元，合肥建投未来创投基金完成备案', '据合肥国投消息，11月25日，由合肥建投旗下合肥国投联合合肥市相关县区投资机构共同发起设立的合肥建投未来创业投资基金合伙企业（有限合伙），完成中国证券投资基金业协会登记备案。基金总规模10亿元，重点布局人工智能、具身智能机器人、脑机接口、未来空间及未来制造等未来产业领域。', 'published', NULL, FALSE, 100, 1, '2026-11-26T23:17:11Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-d1dd57bb289fdf6e', '100001', 'news-category-finance-flash', 'em-202611273941005182-e0d6cc0d3f', '41万亿险资持续探路“向新”“向实”', '金融监管总局日前披露的最新数据显示，截至三季度末，保险公司资金运用余额41.64万亿元。接下来，钱往哪投？波动怎么消化？带着这些问题，记者近期调研采访多家上市险企与保险资管机构。答案正在浮现：投资路径在变，方向不断校准，朝着“向新”“向实”的方向持续探路。', 'published', NULL, FALSE, 100, 1, '2026-11-26T23:15:44Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-06b406c1f4381061', '100001', 'news-category-finance-flash', 'em-202611273941044529-6e62ae18e7', 'SAP考虑在重组中裁减至少1万个岗位', '据报道，SAP正制定一项裁减至少1万个岗位的计划，以推动其软件业务向人工智能时代转型。知情人士表示，此次重组将影响至少9%的全球员工。', 'published', NULL, FALSE, 100, 1, '2026-11-26T23:13:11Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-e40b4fdc1769a5e2', '100001', 'news-category-finance-flash', 'em-202611273941008546-39a30869a0', '公募密集自购 多路增量资金持续入场', '市场震荡之际，公募机构逆势自购权益类基金，“自购潮”再度上演。更多增量“活水”同步入场：新基金积极发行，私募加码自购，ETF也持续获得资金净流入。在政策引导中长期资金入市的背景下，增量资金能否助力夯实市场底部，成为当下市场关注的焦点。', 'published', NULL, FALSE, 100, 1, '2026-11-26T23:11:48Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-da326a1b99ccd481', '100001', 'news-category-finance-flash', 'em-202611273941044247-636313e550', '中国神华：拟配售新H股净筹约67.26亿港元', '11月27日早间，中国神华在港交所公告，于2026年11月26日（香港联交所交易时段后），公司与配售代理订立配售协议，据此，配售代理已同意作为本公司的配售代理按尽力基准促使不少于六名承配人，以每股配售股份38.10港元的配售价认购最多1.77亿股配售股份。', 'published', NULL, FALSE, 100, 1, '2026-11-26T23:11:11Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-f3a035e1f632cfc9', '100001', 'news-category-finance-flash', 'em-202611273941044423-87e5202ba8', '腾讯AI研究成果登上《Nature》主刊', '腾讯透露其生命科学实验室一项AIforScience（科学智能）研究成果近期登上顶级期刊《Nature》主刊。这项研究挑战了药物研发领域一个前沿难题，即不依赖已有的分子模板，用AI从头设计高活性双靶点治疗性多肽。研究团队在减重降糖、肿瘤免疫两个药理方向完成验证。研究仍处于临床前阶段，尚未开展人体临床试验。', 'published', NULL, FALSE, 100, 1, '2026-11-26T23:10:47Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-563af35fd512f87a', '100001', 'news-category-finance-flash', 'em-202611273941044627-dfc3489c93', '看通集团：出售175万股中国星股份 总代价约1301万港元', '看通集团（01059.HK）发布须予披露交易公告，于2026年11月26日，公司在市场上出售合共175万股中国星股份，平均价格为每股7.43港元，总代价约为1301万港元（不包括交易成本）。出售事项完成后，集团不再持有中国星股份。集团预计将确认未经审核收益约928.3万港元。', 'published', NULL, FALSE, 100, 1, '2026-11-26T23:09:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-53a14a5f2f3cf712', '100001', 'news-category-finance-flash', 'em-202611273941040131-d3ee527aa9', '“AI+文化”融资新赛点：只讲故事不够了 全员进入交付战', '过去两年间，人工智能早已不再是技术话题，它深刻嵌进千行百业、渗透到每一个企业的毛细血管里，彻底改写了创业和投融资逻辑。', 'published', NULL, FALSE, 100, 1, '2026-11-26T23:09:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-933b302f1e3c7a1f', '100001', 'news-category-finance-flash', 'em-202611273941043925-ac6a69ae1f', 'Trabuco将于明年出任巴西财政部长', '巴西总统府称，Luiz Carlos Trabuco已接受巴西总统卢拉的邀请，将于明年出任巴西财政部长。', 'published', NULL, FALSE, 100, 1, '2026-11-26T23:08:19Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-6693d9aa8279c88e', '100001', 'news-category-finance-flash', 'em-202611273941038048-0b3e8971e9', '2026全球系统重要性银行公布，5家中资大行档位不变', '11月26日，金融稳定理事会（FSB）公布2026全球系统重要性银行（G-SIB）名单，共计29家机构进入名单，数量与上年保持一致。五家中资大行全部在列，档位与上年保持不变，工商银行仍居第三档，农业银行、中国银行、建设银行位于第二档，交通银行位于第一档。', 'published', NULL, FALSE, 100, 1, '2026-11-26T23:07:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-d547711fcef3172c', '100001', 'news-category-finance-flash', 'em-202611273941043116-f6f10b3e35', '西班牙前央行行长德科斯势将成为新任欧洲央行行长', '欧洲理事会主席安东尼奥·科斯塔当地时间11月26日在社媒平台发文称，欧元区成员国已达成共识，建议提名西班牙前央行行长、现任国际清算银行总经理巴勃罗·埃尔南德斯·德科斯（PabloHernándezdeCos）出任欧洲央行行长，并提名劳伦斯·布恩（LaurenceBoone）和马库斯·布鲁内迈尔（MarkusBrunnermeier）担任欧洲央行执行委员会成员。', 'published', NULL, FALSE, 100, 1, '2026-11-26T23:05:11Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-2c33cfbc72a1be18', '100001', 'news-category-finance-flash', 'em-202611273941042975-fe8d1be8bb', '贝斯特材：拟全球发售3999.9万股H股，最高发售价7港元', '11月27日早间，贝斯特材在港交所公告，公司拟全球发售39,999,000股H股，香港发售股份4,000,000股H股，国际发售股份35,999,000股H股；最高发售价为每股7.00港元；预期股份将于2026年12月7日开始在香港联交所买卖。', 'published', NULL, FALSE, 100, 1, '2026-11-26T23:05:11Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-fa254b08ce281ac3', '100001', 'news-category-finance-flash', 'em-202611273941042777-aec1bb8522', '袁记食品：拟全球发售1631.23万股H股，最高发售价28港元', '11月27日早间，袁记食品在港交所公告，公司拟全球发售16,312,300股H股，香港发售股份1,631,300股H股，国际发售股份14,681,000股H股；最高发售价为每股28.00港元；预期股份将于2026年12月7日开始在香港联交所买卖。', 'published', NULL, FALSE, 100, 1, '2026-11-26T23:02:41Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-1da07bfb7a0a236f', '100001', 'news-category-finance-flash', 'em-202611273941042033-0a586ce91d', '美股股指期货高开 纳指期货、标普500指数期货均涨超0.6%', '美股股指期货高开，其中纳指期货、标普500指数期货均涨超0.6%。', 'published', NULL, FALSE, 100, 1, '2026-11-26T23:00:49Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-7e4461f1c68639a4', '100001', 'news-category-finance-flash', 'em-202611273941037722-d3eb9a00d3', '太空环境解锁阿尔茨海默病差异化分子反应', '美国加州大学圣迭戈分校桑福德综合太空干细胞研究中心主任艾里森·穆特里手持一个含有脑类器官的板块。研究人员将这些类器官送入太空，增添了对阿尔茨海默病的新见解。', 'published', NULL, FALSE, 100, 1, '2026-11-26T22:55:11Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-8776884b2bb5db65', '100001', 'news-category-finance-flash', 'em-202611273941037635-4d66a143e8', '中国神华：H股配售价每股38.10港元 预计融资约67.4亿港元', '中国神华在港交所公告，拟以每股38.10港元配售最多1.77亿股，预计所得款项总额约67.4亿港元。配售价较前收盘价折让7.7%。约90%的所得款项净额将用于偿还境内债务及优化资本结构。', 'published', NULL, FALSE, 100, 1, '2026-11-26T22:54:22Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-8bc6a2c8399b8d2e', '100001', 'news-category-finance-flash', 'em-202611273941037531-aeffa7f355', '横琴粤澳深度合作区前10个月进出口值同比增超六成', '据拱北海关统计，今年前10个月，横琴粤澳深度合作区进出口值为634.4亿元，同比增长66.8%。其中10月当月进口值达22亿元，同比增长87.8%；超2000吨跨境电商货品走出国门，远销20个国家和地区。', 'published', NULL, FALSE, 100, 1, '2026-11-26T22:51:34Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-75dfd36324252f60', '100001', 'news-category-finance-flash', 'em-202611273941037070-1954dff7ba', '两融新规落地在即 券商信用业务加快精细化管理', '融资保证金比例调整自11月30日起正式实施，沪深北交易所将投资者融资买入证券的最低保证金比例由100%下调至80%，同时将存量合约纳入调整范围。11月26日，中国证券报记者采访多位券商人士了解到，随着新规落地临近，券商正加快业务和系统准备，营业部客户对融资额度、保证金可用余额及追保平仓安排的咨询有所增加。', 'published', NULL, FALSE, 100, 1, '2026-11-26T22:50:03Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-ff00dc12d1f3c294', '100001', 'news-category-finance-flash', 'em-202611273941036849-ce4d74d7e0', '资金借道ETF入市 7月以来净流入超万亿', '近日，A股市场持续震荡，大量资金“越跌越买”。11月25日，逾370亿元资金借道ETF入市。值得关注的是，7月以来的市场调整中，ETF成为资金进场的重要通道。Wind数据显示，7月1日至11月25日，全市场ETF累计净流入约1.4万亿元，沪深300等核心宽基指数成为“压舱石”，四只大型沪深300ETF合计净流入超3500亿元。此外，半导体材料设备等细分主题ETF也获资金积极加仓。', 'published', NULL, FALSE, 100, 1, '2026-11-26T22:48:08Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-112fe159393380c5', '100001', 'news-category-finance-flash', 'em-202611273941037493-97ad517587', '首个农耕文明领域大模型“天稷”发布', '从农业农村部了解到，日前首个农耕文明领域大模型“天稷”发布。该模型涵盖8000万条覆盖传统农耕技艺、现代智慧农业与农耕文明演进脉络的知识条目，为农业生产提出智慧决策建议。', 'published', NULL, FALSE, 100, 1, '2026-11-26T22:44:05Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-08b90d6548674ade', '100001', 'news-category-finance-flash', 'em-202611273941036483-b3befd974f', '物理AI峰会催化不断！算力基建景气向好 多股业绩倍增可期(名单)', '根据3家及以上机构一致预测，共7只物理AI概念股明年业绩有望翻倍增长。其中，机构预计沐曦股份净利或同比大增7.2倍，美芯晟净利将增长超4倍，豪恩汽电、罗普特预测净利增幅均在1.9倍以上，经纬恒润、超图软件、尚品宅配的业绩亦有望倍增。', 'published', NULL, FALSE, 100, 1, '2026-11-26T22:43:30Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-d2595bdf5a20ac8b', '100001', 'news-category-finance-flash', 'em-202611273941035511-52c0fca776', '据报道 韩国评估扩大股市稳定基金', '据报道，韩国评估扩大股市稳定基金。', 'published', NULL, FALSE, 100, 1, '2026-11-26T22:42:22Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-dcfc57b0dbe83bd4', '100001', 'news-category-finance-flash', 'em-202611273941005315-9603a2ca14', '固态冲刺量产 场景抢先卡位 锂电产业寻找新增长极', '巨湾技研创始人兼CTO黄向东判断，发展固态电池是锂电行业的大趋势。虽然头部电池企业及车企悉数入局，但大规模量产固态电池并非易事。丰田作为全球固态电池投入最早、决心最大的企业，其固态电池装车计划自2017年首次提出以来已四次推迟，背后折射出固态电池行业整体的困局。', 'published', NULL, FALSE, 100, 1, '2026-11-26T22:40:49Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-3ee4930b04d005bd', '100001', 'news-category-finance-flash', 'em-202611273941034640-3c6662034d', '以军称空袭黎巴嫩真主党武装训练营目标', '当地时间26日晚间，以色列国防军发表声明说，以军不久前对黎巴嫩南部一处属于黎巴嫩真主党精锐部队“拉德万部队”的训练营实施空袭，摧毁了数十枚火箭弹及发射装置。黎巴嫩真主党方面暂未作出回应。', 'published', NULL, FALSE, 100, 1, '2026-11-26T22:38:43Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-a22506c8eaf60879', '100001', 'news-category-finance-flash', 'em-202611273941033167-0034146546', '古巴今年已批40个外资参与项目 总额约20亿美元', '古巴副总理兼贸易和外国投资部部长佩雷斯-奥利瓦26日在第42届哈瓦那国际博览会期间表示，古巴今年已批准40个外资参与的投资项目，总投资额约20亿美元。', 'published', NULL, FALSE, 100, 1, '2026-11-26T22:23:39Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-55cb608082f6662b', '100001', 'news-category-finance-flash', 'em-202611273941005074-65c41d88a5', 'A股上市公司锚定主业积极扩产 海外产能布局成重要投资方向', '梳理发现，近期，多家上市公司相继披露扩产计划，投资领域涵盖电子信息、新能源、先进制造等产业链，部分项目投资额达数十亿元。有上市公司负责人表示，与单纯扩大生产规模不同，此轮投资更多聚焦企业主营业务，既着眼于满足下游需求增长，也注重高端产品布局和全球产能配置，显示出企业深耕主业、谋求长远发展的投资取向。', 'published', NULL, FALSE, 100, 1, '2026-11-26T22:17:43Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-91a4ee6960bc2ce6', '100001', 'news-category-finance-flash', 'em-202611273941028398-6d8661e0fc', '周五你需要知道的隔夜全球要闻：特朗普指责政府低报经济增长并要求调查；联合国预计今年全球海运贸易“零增长”；欧央行迎来新任掌门人', '1、特朗普指责自己的政府“蓄意”低报美国经济增长，他抓住一次GDP数据的例行修正，以此作为其提出选举干预指控的依据，要求立即对此展开调查，但并未提供任何证据。2、马斯克表示将每年向美国所有孩子再捐赠一份SpaceX股份。', 'published', NULL, FALSE, 100, 1, '2026-11-26T22:03:08Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-76838f02ecee9a60', '100001', 'news-category-finance-flash', 'em-202611273941025968-1eedd24bd3', '日本能源集团JERA计划在电厂附近建设Anthropic、Meta数据中心', '日本能源集团JERA计划在电厂附近建设Anthropic、Meta数据中心，也在与亚马逊、微软和谷歌进行洽谈。', 'published', NULL, FALSE, 100, 1, '2026-11-26T21:58:35Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-c4c36fb90a73aca8', '100001', 'news-category-finance-flash', 'em-202611273941023842-f12d3da438', '强风暴袭击美国东海岸 致数十万用户停电 数千航班受扰', '当地时间11月26日，一场强风暴袭击美国东海岸大部分地区，导致数十万用户停电。弗吉尼亚州、马里兰州、宾夕法尼亚州、新泽西州和北卡罗来纳州等受到电力中断影响。风暴也扰乱了当地的航空出行。截至当天下午早些时候，美国已有400多个航班取消、约1600个航班延误，华盛顿和纽约地区主要机场受影响尤为严重。', 'published', NULL, FALSE, 100, 1, '2026-11-26T21:44:33Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-d6f2f757bf4936fd', '100001', 'news-category-finance-flash', 'em-202611273941023222-fc80908a2c', '富时A50期指连续夜盘收跌0.02% 报12511点', '富时A50期指连续夜盘收跌0.02%，报12511点。', 'published', NULL, FALSE, 100, 1, '2026-11-26T21:34:22Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-c5151041c90375ee', '100001', 'news-category-finance-flash', 'em-202611273941022938-904679cd85', '马斯克将每年向美国儿童再捐赠一份SpaceX股份', '马斯克在X上发帖称，他将每年向美国所有孩子再捐赠一份SpaceX股份。', 'published', NULL, FALSE, 100, 1, '2026-11-26T21:30:24Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-d5a57ff72b2001a7', '100001', 'news-category-finance-flash', 'em-202611273941020094-3090ff12c5', '多伦多股票指数收盘上涨246.89点 涨幅0.72% 报34426.88点', '多伦多股票指数收盘上涨246.89点，涨幅0.72%，报34426.88点。', 'published', NULL, FALSE, 100, 1, '2026-11-26T21:04:30Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-73b0ae020c87c389', '100001', 'news-category-finance-flash', 'em-202611273941019364-f65efe1219', '国际原子能机构表示 正与俄罗斯和乌克兰就第九次局部停火的安排进行接触', '国际原子能机构表示，在扎波罗热核电站再次失去外部供电后，正与俄罗斯和乌克兰就第九次局部停火的安排进行接触。', 'published', NULL, FALSE, 100, 1, '2026-11-26T21:00:35Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-4714946ed893f68d', '100001', 'news-category-finance-flash', 'em-202611273941019039-e1d1c0bc91', '巴西雷亚尔大涨2.7% 因市场押注特拉布科将加入卢拉政府担任财政部长', '巴西雷亚尔大涨2.7%，因市场押注特拉布科将加入卢拉政府担任财政部长。', 'published', NULL, FALSE, 100, 1, '2026-11-26T20:59:14Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-3f764a1bb612903a', '100001', 'news-category-finance-flash', 'em-202611273941016813-413c893806', '巴西基准股指涨超5% 触及盘中高点', '巴西基准股指涨超5%，触及盘中高点。', 'published', NULL, FALSE, 100, 1, '2026-11-26T20:36:04Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-eb4680a36d4bcea0', '100001', 'news-category-finance-flash', 'em-202611273941016544-07fc7b2ac2', '美元指数上涨', '美元指数上涨。截至纽约汇市尾市，1欧元兑换1.0972美元，低于前一交易日的1.0980美元；1英镑兑换1.3108美元，低于前一交易日的1.3122美元。', 'published', NULL, FALSE, 100, 1, '2026-11-26T20:16:48Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-1fc76787654b0b2b', '100001', 'news-category-finance-flash', 'em-202611273941013567-22ff212db8', '世界黄金协会：黄金在不同经济周期中均具配置韧性', '11月26日，世界黄金协会发布关于不同经济周期中黄金配置比例最新研究报告。报告认为，黄金在不同经济周期中均展现出较强韧性。在投资组合中保持一定比例的黄金配置，有助于改善整体组合表现。投资者可根据不同经济周期下各类资产的表现，动态调整黄金配置比例。', 'published', NULL, FALSE, 100, 1, '2026-11-26T20:10:59Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-a24390556bd99a45', '100001', 'news-category-finance-flash', 'em-202611273941013753-6f178f6a79', '伦铜自11个月低点反弹 科技股上涨提振工业金属', '伦铜周四由11个月低点反弹，其他大宗商品和科技股也走高，连续数日大幅下跌后，投资者重返风险较高的资产。LME 3个月期铜期货结算价上涨1.9%，部分收复本月以来的跌幅。铜价反弹与市场风险偏好的普遍改善同步，科技股在多个市场领涨，欧洲矿业股也走高。美国股指期货上涨，此前周三尾盘买盘推动纳斯达克100指数从熊市边缘回升。', 'published', NULL, FALSE, 100, 1, '2026-11-26T19:50:58Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-3ee84303e9ea5236', '100001', 'news-category-finance-flash', 'em-202611273941012856-813db872f7', '法国总统马克龙表示 若今年未达成协议 欧盟预算谈判将于2027年下半年重启', '法国总统马克龙表示，若今年未达成协议，欧盟预算谈判将于2027年下半年重启。', 'published', NULL, FALSE, 100, 1, '2026-11-26T19:45:42Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-1f149361bba4afa4', '100001', 'news-category-finance-flash', 'em-202611273941007295-5df427dee7', '《新一代通信网建设实施方案》发布 适时开展6G网络建设 二〇三〇年建成新一代通信网', '工业和信息化部、国家网信办、国家发展改革委日前印发《新一代通信网建设实施方案》（以下简称《实施方案》），提出到2030年，建成覆盖完善、性能领先的新一代通信网。', 'published', NULL, FALSE, 100, 1, '2026-11-26T19:38:43Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-19e3e61727f04fa5', '100001', 'news-category-finance-flash', 'em-202611273941012514-3848055bb5', '土耳其央行暂停一周期回购拍卖', '土耳其央行暂停一周期回购拍卖。', 'published', NULL, FALSE, 100, 1, '2026-11-26T19:18:01Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-6ca5e9a34056c85c', '100001', 'news-category-finance-flash', 'em-202611273941012035-01d6be8ff9', '在岸人民币兑美元北京时间03:00收报6.6609元', '在岸人民币兑美元（CNY）北京时间03:00收报6.6609元，较周三夜盘收盘涨72点。成交量469.21亿美元。', 'published', NULL, FALSE, 100, 1, '2026-11-26T19:09:33Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-3cdef4aad3ccabd0', '100001', 'news-category-finance-flash', 'em-202611273941011957-4380fcce1a', '恒生指数主连夜盘收跌0.38% 恒生科技指数主连夜盘收跌0.50%', '恒生指数主连夜盘收跌0.38%，报22117点；恒生科技指数主连夜盘收跌0.50%，报3398点。', 'published', NULL, FALSE, 100, 1, '2026-11-26T19:04:55Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-d6a23afd081c3a9a', '100001', 'news-category-finance-flash', 'em-202611273941011775-e2246b7887', '币安表示 我们的提现恢复工作已完成 10月安全事件导致的提现暂停已全面解除', '币安表示，我们的提现恢复工作已完成，10月安全事件导致的提现暂停已全面解除。', 'published', NULL, FALSE, 100, 1, '2026-11-26T18:50:51Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-50edd7b496ab8acd', '100001', 'news-category-finance-flash', 'em-202611273941007697-df0e2cf265', '公募深耕ESG投资 打通长期资金入市通道', '近年来，公募基金行业积极围绕金融“五篇大文章”，推动绿色金融发展，持续践行可持续发展理念。从公司战略到投研体系，从产品矩阵到“积极股东”实践，再到面向未来的持续布局，环境、社会和公司治理（ESG）正由理念转化为可执行的投资标准与资金配置行动。', 'published', NULL, FALSE, 100, 1, '2026-11-26T18:49:43Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-3c294d3450e4af0a', '100001', 'news-category-finance-flash', 'em-202611273941005219-d65db482e3', 'SpaceX获准部署太空数据中心星座 新一轮太空算力竞赛开启', '当地时间11月25日，美国联邦通信委员会（FCC）宣布，附条件批准美国太空探索技术公司（SpaceX）部署至多100万颗卫星，组建名为“Starmind”的太空数据中心星座。这是美国监管机构首次为太空数据中心星座颁发此类许可。', 'published', NULL, FALSE, 100, 1, '2026-11-26T18:30:48Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-a98d5c2a8469ccb6', '100001', 'news-category-finance-flash', 'em-202611273941007053-bf84c75455', '光伏行业并购升温 中小厂商整合提速', '进入11月，光伏行业并购、重整等资本运作步伐明显加快，产业资本及跨界投资人等相继入场，部分中小光伏厂商在这轮整合中被“吃掉”，产业资源向头部企业集中。被收购产能是否真正退出，行业供需关系能否有效改善，备受业内关注。由于头部企业现金流尚有支撑，真正影响供需形势的大型兼并尚未看到眉目，业内对于明年即将落地实施的能耗新规抱有期待，但能否助推产能出清还有待检验。', 'published', NULL, FALSE, 100, 1, '2026-11-26T18:24:56Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-73e5d77048024294', '100001', 'news-category-finance-flash', 'em-202611273941008851-c7eef5e06b', '特朗普指责美国政府在中期选举前“蓄意”低报GDP增速 要求立即调查', '感恩节当天，美国总统特朗普以三季度GDP增速由3.4%上修至4.3%为由，指责其领导的政府在中期选举前“蓄意”低报经济增长，要求立即调查，但尚未提供证据。', 'published', NULL, FALSE, 100, 1, '2026-11-26T18:15:17Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-a9982b8e27a1a6e1', '100001', 'news-category-finance-flash', 'em-202611273941008071-bd33c0e66f', '沙特吉赞炼油厂据悉因遇袭而暂时中断了一些活动', '沙特吉赞炼油厂据悉因遇袭而暂时中断了一些活动。', 'published', NULL, FALSE, 100, 1, '2026-11-26T18:10:39Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-0e7b8c6da6c4452d', '100001', 'news-category-finance-flash', 'em-202611273941008191-98057d5894', '德国总理默茨表示：德国无法接受现有的欧盟2028-2034年预算提案', '德国总理默茨表示，德国无法接受现有的欧盟2028-2034年预算提案。', 'published', NULL, FALSE, 100, 1, '2026-11-26T18:07:20Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-fee26052d0b78bca', '100001', 'news-category-finance-flash', 'em-202611273941007168-0a33cc1f13', 'Altria和日本烟草探索收购英国烟草公司帝国品牌', 'Altria和日本烟草探索收购英国烟草公司帝国品牌。', 'published', NULL, FALSE, 100, 1, '2026-11-26T18:02:39Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-b69c11f556624aff', '100001', 'news-category-finance-flash', 'em-202611273941003534-e910ec6465', '巴西副总统：美国对巴西加征新关税完全不合理', '当地时间11月26日，巴西副总统阿尔克明表示，美国提出对巴西加征的新关税完全不合理，巴西政府将尽全力扭转这一局面。阿尔克明强调，世界上不存在航空领域的关税，航空这样具有战略意义的领域不征收关税是传统。当地时间11月25日，美国贸易代表办公室发布一项提议，要求对从巴西进口的糖征收特定额外关税；取消对巴西成品飞机的关税豁免，征收10%从价关税。据悉，成品飞机是巴西对美出口的主要产品之一，属于豁免清单中的产品，其出口额在巴西2024年对美出口产品中排名第四。', 'published', NULL, FALSE, 100, 1, '2026-11-26T17:55:40Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-2f878dcd61d48cd2', '100001', 'news-category-finance-flash', 'em-202611273941004755-7bb41c92ab', '尼日利亚中部一村庄遭袭 死亡人数升至74人', '尼日利亚中部尼日尔州政府26日说，该州21日发生的一起袭击事件已造成74人死亡。尼日尔州州长穆罕默德·奥马鲁·巴戈26日在冲突事发村庄对媒体说，此次袭击已造成74人死亡，他已下令展开调查。该州政府22日发表声明说，武装人员21日凌晨袭击该州一个村庄，造成至少5人死亡、5人受伤。当地消息人士接受媒体采访时说，此次袭击可能是一起族群冲突后的报复。', 'published', NULL, FALSE, 100, 1, '2026-11-26T17:45:09Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-f6964340dbd7cccf', '100001', 'news-category-finance-flash', 'em-202611273941004674-4ca35f9add', '墨西哥总统谴责美国缉毒局干涉墨内政', '当地时间11月26日，墨西哥总统辛鲍姆在新闻发布会上谴责美国缉毒局开设面向墨西哥民众的匿名举报渠道，称此举是对墨西哥内政的干涉。辛鲍姆强调，墨西哥拥有负责打击有组织犯罪的执法机构。她敦促美国缉毒局将精力放在打击美国境内的贩毒活动上，调查与有组织犯罪相关的腐败问题、毒品分销网络及非法资金流向。', 'published', NULL, FALSE, 100, 1, '2026-11-26T17:32:25Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-4c2be347632028c8', '100001', 'news-category-finance-flash', 'em-202611273941004268-43a29caeb7', '欧洲股市反弹 投资者谨慎重返AI交易', '欧洲股市周四反弹，结束两连跌，投资者谨慎重返人工智能(AI)交易，推动科技股上涨。此次反弹表明，在经历大幅抛售后，投资者重返股市的意愿正在增强。欧洲市场的AI交易表现突出，瑞银集团编制的一篮子半导体股票上涨3.9%，一篮子AI受益股上涨3.2%。Soitec、意法半导体和阿斯麦等芯片制造商大幅上涨。', 'published', NULL, FALSE, 100, 1, '2026-11-26T17:20:49Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-eb786491a505f7c8', '100001', 'news-category-finance-flash', 'em-202611273941003916-96fb3fe4f4', 'ICE罗布斯塔咖啡期货涨超3% 至每吨2856美元', 'ICE罗布斯塔咖啡期货涨超3%，至每吨2856美元。', 'published', NULL, FALSE, 100, 1, '2026-11-26T17:18:20Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-82146a05737c4cb2', '100001', 'news-category-finance-flash', 'em-202611273941003846-838d45e72a', '欧洲理事会主席科斯塔表示：欧元区成员国已同意推荐巴勃罗·埃尔南德斯·德科斯（西班牙籍）担任欧洲央行行长', '欧洲理事会主席科斯塔表示，欧元区成员国已同意推荐巴勃罗·埃尔南德斯·德科斯（西班牙籍）担任欧洲央行行长。', 'published', NULL, FALSE, 100, 1, '2026-11-26T17:14:25Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-e3c976c8cd052511', '100001', 'news-category-finance-flash', 'em-202611273941003178-8d6272474a', '夜盘期货收盘：沪锌收涨1.59% 沪铅收涨1.51%', '国际铜夜盘收跌0.13%，沪铜收涨0.56%，沪铝收涨0.43%，沪锌收涨1.59%，沪铅收涨1.51%，沪镍收涨2.32%，沪锡收涨0.52%。氧化铝夜盘收跌0.12%，铝合金收涨0.29%。不锈钢夜盘收涨0.96%。', 'published', NULL, FALSE, 100, 1, '2026-11-26T17:05:09Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-60543a3599ed5202', '100001', 'news-category-finance-flash', 'em-202611273941001924-658fc935be', '伊朗否认袭击了科威特一处关键设施', '伊朗否认袭击了科威特一处关键设施。', 'published', NULL, FALSE, 100, 1, '2026-11-26T16:52:50Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-30ab1cda403ccd40', '100001', 'news-category-finance-flash', 'em-202611273941000238-eacd2ccd6a', '联合国贸发会议报告：2026年全球海运贸易量预计零增长', '当地时间11月26日，联合国贸易和发展会议（贸发会议）发布的一份报告显示，2026年全球海运贸易量预计零增长，而这一数据在2025年为1.9%。', 'published', NULL, FALSE, 100, 1, '2026-11-26T16:36:53Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-37faa8090e1bca36', '100001', 'news-category-finance-flash', 'em-202611263940955620-9c7d82a086', '“摘星脱帽” *ST春天停牌一天！再度触发退市风险警示的隐患仍存', '11月26日盘后，*ST春天披露公告称，上海证券交易所已同意公司撤销退市风险警示及其他风险警示，公司股票将于11月27日停牌一天，11月30日起复牌，证券简称由“*ST春天”变更为“青海春天”，股票代码不变，涨跌幅限制仍为10%。', 'published', NULL, FALSE, 100, 1, '2026-11-26T16:35:25Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-cb0c405ca2bfa30a', '100001', 'news-category-finance-flash', 'em-202611273941000158-1ee2e39da8', '欧洲主要股指集体收涨 德国DAX指数涨超2%', '英国富时100指数上涨1.77%；德国DAX指数上涨2.14%，法国CAC40指数上涨1.71%，欧洲STOXX600指数上涨1.83%。', 'published', NULL, FALSE, 100, 1, '2026-11-26T16:33:01Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-3e350a7d7baae80f', '100001', 'news-category-finance-flash', 'em-202611273940999943-466414c234', '渣打银行扩展量子计算研究计划', '渣打银行宣布扩大其量子计算研究计划。该行在新加坡金管局（MAS）FSTI量子技术计划支持下成功完成首年研究，在语言建模、时间序列预测及金融衍生品定价三大领域取得进展。研究显示，量子方法可将可训练参数减少18倍、计算迭代减少至多18倍。渣打表示，下一阶段将基于首年成果，继续评估量子技术在高度监管的金融服务环境中的采用准备度。', 'published', NULL, FALSE, 100, 1, '2026-11-26T16:31:10Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-0e2405446c12fc05', '100001', 'news-category-finance-flash', 'em-202611263940962643-698b71a2d8', '业绩大增、股价大跌！封测巨头通富微电董事长提议最高3亿元回购', '11月26日晚间，通富微电发布公告，公司董事长石磊提议以集中竞价交易方式回购公司股份，资金总额在1.5亿元至3亿元之间。 本次提议回购的股份，将全部用于股权激励或员工持股计划。石磊表示，此次提议回购基于对公司未来发展前景的信心以及对公司股票价值的认可，旨在维护全体股东利益并健全长效激励机制。 他同时承诺将推动董事会尽快审议该事项，并在董事会上投出赞成票。', 'published', NULL, FALSE, 100, 1, '2026-11-26T16:17:39Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-d30a0149d5a81440', '100001', 'news-category-finance-flash', 'em-202611273940998659-24150d74cc', '据报道：德国软件巨头SAP正考虑在重组中裁减至少1万个工作岗位', '据报道，德国软件巨头SAP正考虑在重组中裁减至少1万个工作岗位。', 'published', NULL, FALSE, 100, 1, '2026-11-26T16:17:03Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-a101f95104ec79e4', '100001', 'news-category-finance-flash', 'em-202611263940969793-e2ca128fa2', '官宣！马斯克旗下脑机接口公司获准开展关键性临床试验', '11月26日消息，马斯克旗下脑机接口公司Neuralink宣布，已获得美国食品药品监督管理局（FDA）批准，开展LINK关键性临床试验，并已向成年渐冻症（ALS）患者开放招募。据该公司称，这是美国首个植入式脑机接口关键性试验，意味着该公司已进入上市申报前的关键临床验证阶段。若试验取得足以支持申报的安全性和有效性证据，Neuralink有望向FDA提交上市申请。此外，北京时间11月26日，马斯克在社交平台X发文表示，每名美国儿童将获得两股SpaceX A类普通股，一股由SpaceX公司赠予，另一股由马斯克个人出资赠予。截至11月25日收盘，SpaceX 股价为127.44美元/股。', 'published', NULL, FALSE, 100, 1, '2026-11-26T16:16:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-9fb6ea66322d1cfb', '100001', 'news-category-finance-flash', 'em-202611263940967756-e729032abf', '广药集团全资平台入局*ST香雪重整 16.88亿元换29.99%股份 拟取得控股权', '11月26日晚间，*ST香雪公告，11月25日，管理人与广州广药资本有限公司（下称广药资本）签署《重整投资协议》。按方案，公司以6.5872亿股为基数，按每10股转增14股实施资本公积金转增，共转增9.2221亿股；广药资本以3.56元/股支付16.88亿元，取得4.7412亿股转增股票，占转增后总股本约29.99%。公告称，如方案顺利实施并最终完成，重整程序完成后公司控制权可能发生变化，控股股东可能变更为广药资本。广药资本为广药集团全资子公司，成立于2026年2月13日，注册资本20亿元。', 'published', NULL, FALSE, 100, 1, '2026-11-26T16:15:22Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-07bc8bd8ecab4b2a', '100001', 'news-category-finance-flash', 'em-202611263940961328-eac24f9ab0', '超配中国！摩根大通：AI周期仍在延续 看多2027年亚洲股市', '近期，摩根大通在最新发布的《2027年亚洲展望》报告中对亚洲股市给出看多判断，将中国内地、中国香港与韩国一同列入超配名单。在其看来，市场最新一轮的下行周期似乎已经结束。若上述判断成立，周期条件有望在2027年上半年修复，一如2025年下半年的情形；亚洲股市的上升轨迹将由AI资本开支与应用落地、安全与韧性支出，以及增长持稳、通胀缓和的全球宏观环境共同驱动。', 'published', NULL, FALSE, 100, 1, '2026-11-26T16:14:49Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-c99526d6d86c255f', '100001', 'news-category-finance-flash', 'em-202611263940988143-c4bad33873', '股价上涨210%、七次提示异动 冰山冷热再发公告：两个热点概念年内几无收入', '11月26日晚间，冰山冷热披露《股票交易异常波动暨风险提示公告》。公告显示，公司股票在2026年11月25日与11月26日连续两个交易日内，收盘价格涨幅偏离值累计超过20%，再度属于股票交易异常波动情形。', 'published', NULL, FALSE, 100, 1, '2026-11-26T16:13:09Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-33ce581f7413878e', '100001', 'news-category-finance-flash', 'em-202611263940903659-aa6c6b6902', '五连板后 克来机电收监管工作函', '11月26日晚，上交所官网显示，上交所向克来机电（603960）下发监管工作函，处理事由为“关于上海克来机电自动化工程股份有限公司有关股价波动事项”，涉及对象为上市公司。在收到监管工作函的同时，克来机电当晚还同时发布股票交易的风险提示性公告。首先就提示了公司股票交易非理性炒作过热，存在随时下跌风险。', 'published', NULL, FALSE, 100, 1, '2026-11-26T16:13:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-2caa28a85536d635', '100001', 'news-category-finance-flash', 'em-202611263940966497-5d32920e15', '万亿级算力产业链迎利好！广东：鼓励算力中心优先使用国产算力芯片', '万亿级算力产业链迎利好！11月26日下午，广东省政务服务和数据管理局、广东省发展和改革委员会印发《广东省算力发展“十五五”规划》（简称《规划》），目标到2028年，广东算力发展取得重要阶段性成效，智算规模突破1000 EFlops（FP16），全省数据中心绿电使用占比超80%，新建大型及以上数据中心电能利用效率（PUE）小于1.2，存量数据中心能效显著提升，绿色低碳发展达到全国先进水平，边缘智算深入推进，算力设施建设布局持续优化，算力网络时延进一步降低，数算电网一体化协同建设水平显著提升，基本建成国际一流、国内领先的算力高地。', 'published', NULL, FALSE, 100, 1, '2026-11-26T16:12:53Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-5fced194cfb7858a', '100001', 'news-category-finance-flash', 'em-202611263940937141-5aadf4c27c', '回购活跃态势延续 多家A股公司公告：回购并全部注销', '11月26日晚间，上市公司回购公告接力推出，A股市场回购活跃态势延续。', 'published', NULL, FALSE, 100, 1, '2026-11-26T16:12:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-4b5f004c261ba50b', '100001', 'news-category-finance-flash', 'em-202611263940959263-af567ba26c', '*ST闻泰年内第三次下修可转债转股价 今年已从43.60元调整至18元', '11月26日晚间，*ST闻泰（600745.SH）发布公告，决定将“闻泰转债”的转股价格由18.36元/股向下修正至18.00元/股。本次修正后的转股价格自2026年11月30日起生效，“闻泰转债”将于11月27日停止转股一天，并于11月30日起恢复转股并执行新价格。这是“闻泰转债”在2026年年内第三次转股价格下调，也是该债券自发行以来的第4次向下修正。', 'published', NULL, FALSE, 100, 1, '2026-11-26T16:11:08Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-360e04c103db6f5f', '100001', 'news-category-finance-flash', 'em-202611263940940729-9960b26511', '让渐冻症患者重新“开口” 我国首例无线侵入式汉语言脑机接口临床试验成功', '让渐冻症患者重新“开口”！近日，我国首例无线侵入式汉语言脑机接口临床试验，成功帮助重度渐冻症构音障碍患者实现言语交流。', 'published', NULL, FALSE, 100, 1, '2026-11-26T16:09:29Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-2ba77aad29eda89e', '100001', 'news-category-finance-flash', 'em-202611263940905024-e589a3e78e', '中国信通院：国星宇航“星算”计划天秤座卫星标称算力达32PFLOPS', '近日，中国信通院发布了国星宇航“星算”计划02组卫星首批第三方在轨能力测试数据。数据显示，“星算”计划02组天秤座卫星标称算力达32PFLOPS（每秒千万亿次浮点运算），“星算”计划相关技术路线初步可行。', 'published', NULL, FALSE, 100, 1, '2026-11-26T16:08:53Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-7e3626679314c5b4', '100001', 'news-category-finance-flash', 'em-202611263940960560-6effcda544', '知名牛散减持可川科技 此前斥资约8亿元重仓', '牛散屠文斌家族，减持可川科技股份。可川科技(603052)11月26日晚间公告，公司近日收到持股5%以上股东发来的简式权益变动报告书，屠施恩于11月26日通过集中竞价方式减少9300股，占公司总股本的0.00495%。', 'published', NULL, FALSE, 100, 1, '2026-11-26T16:08:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-86b59bac4efd151b', '100001', 'news-category-finance-flash', 'em-202611263940905291-e5a93a17ce', '豁免债务超9亿元、最高1亿元增持 寿光市国资连续出手支持ST晨鸣', '11月26日晚间，ST晨鸣（000488.SZ，即晨鸣纸业）发布提示性公告，公司收到寿光市财政局全资下属企业寿光市人投新能源科技发展有限公司（以下简称寿光人投）的函告，寿光人投计划自公告披露之日起6个月内增持公司股份，拟增持金额不低于5000万元且不超过1亿元。', 'published', NULL, FALSE, 100, 1, '2026-11-26T16:07:32Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-7540c59667acbebc', '100001', 'news-category-finance-flash', 'em-202611263940967823-c50d8ecd27', '上市首日跌超7% 氢氧化锂期货破发 背后供需压力怎么看？', '11月26日，氢氧化锂期货在广州期货交易所（下称“广期所”）正式挂牌上市。这是继碳酸锂期货、期权之后，广期所落地的又一锂电产业链核心品种，进一步增强了新能源金属期货板块服务产业的精准性与有效性。', 'published', NULL, FALSE, 100, 1, '2026-11-26T16:05:45Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-5b438b89041fe4af', '100001', 'news-category-finance-flash', 'em-202611263940930253-422acce53e', '标的估值翻倍至2.5亿美元！凌云光增资PhotonicX AI 加码光通信业务', '为推进全光交换整体解决方案布局，凌云光再度出手加码光互连核心赛道。11月26日晚间，公司披露公告宣布，全资子公司凌云光国际拟使用自有资金620万美元（约合4200万元人民币）向参股公司PhotonicX AI增资，认购其889股A轮优先股。这是凌云光继2025年3月注资后再次向该标的追加投资。交易完成后，凌云光通过旗下两家子公司合计持有的PhotonicX AI股权比例将升至9.385%。本次增资不仅吸引了长飞光纤旗下机构等多方资本参与，也推动标的公司投前估值飙升至2.5亿美元。', 'published', NULL, FALSE, 100, 1, '2026-11-26T16:05:36Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-c8181af3d3ac964d', '100001', 'news-category-finance-flash', 'em-202611263940903560-713655201b', '股价年内接近“腰斩” *ST沐邦最新公告：撤销退市风险警示', '*ST沐邦11月26日晚间公告，上海证券交易所已同意撤销公司股票退市风险警示，但由于其他风险警示情形尚未完全消除，股票简称将由“*ST沐邦”变更为“ST沐邦”，股票继续在风险警示板交易，日涨跌幅限制仍为10%。公司股票将于11月27日开市起停牌1天，11月30日开市起复牌，撤销退市风险警示及继续被实施其他风险警示的实施起始日均为11月30日。', 'published', NULL, FALSE, 100, 1, '2026-11-26T16:03:38Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-cba434efc107a793', '100001', 'news-category-finance-flash', 'em-202611263940965334-3616b22a19', '矛盾和解、换届提名落定！银禧科技新董事候选人浮现“广合系”身影', '11月26日晚间，银禧科技（300221）披露多份公告，包括《关于董事会换届选举的公告》《关于召开2026年第二次临时股东会的通知》等。公司推出新的董事人选，值得注意的是，提名人肖红星与广合科技（001389）实控人名字相同，董事候选人李赳为广合科技实控人旗下企业高管。', 'published', NULL, FALSE, 100, 1, '2026-11-26T16:03:09Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-0b2350c31b7e1578', '100001', 'news-category-finance-flash', 'em-202611263940900342-f5509e11df', '商务部回应美国加征301关税：个别国家以“产能过剩”为名 行保护主义之实', '11月26日，商务部召开例行新闻发布会。此次发布会聚焦美方301调查、欧委会对全球混动汽车发起保障措施调查初步裁定等热点事件，商务部新闻发言人进行了回应。', 'published', NULL, FALSE, 100, 1, '2026-11-26T16:03:09Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-46e007018fa49cc2', '100001', 'news-category-finance-flash', 'em-202611263940888165-fcfab9d106', '交易各方未能就核心诉求达成一致 韩建河山重大资产重组终止', '又有A股上市公司终止重大资产重组。韩建河山（603616）11月26日晚间发布公告称，公司董事会审议通过终止发行股份及支付现金购买辽宁兴福新材料股份有限公司（简称“兴福新材”）99.9978%股份并募集配套资金的议案，将撤回相关申请文件，同时授权管理层办理终止相关事宜。', 'published', NULL, FALSE, 100, 1, '2026-11-26T16:02:27Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-72dd7d7f99d21b23', '100001', 'news-category-finance-flash', 'em-202611263940996393-96de025d19', '斯托克欧洲600指数上涨2%，至638.63点', '斯托克欧洲600指数上涨2%，至638.63点。', 'published', NULL, FALSE, 100, 1, '2026-11-26T15:57:03Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-72df41133eac4212', '100001', 'news-category-finance-flash', 'em-202611263940996490-af8e4c626e', '特朗普指责政府蓄意低报经济增长 要求展开调查', '特朗普指责自己的政府“蓄意”低报美国经济增长，他抓住一次例行数据修正，以此作为其提出选举干预指控的依据，但并未提供任何证据。特朗普周四在社交媒体发帖指出，GDP数据显示美国经济第三季度按年率计算增长4.3%，高于此前公布的3.4%估计值，并称这是一个“重大差异”。特朗普还表示，“我要求立即对此展开调查。这不是一个小错误，而是一个巨大且蓄意造成的错误。”这则帖子是在美国感恩节当天上午从他位于西棕榈滩的高尔夫球场发出的。', 'published', NULL, FALSE, 100, 1, '2026-11-26T15:56:28Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-61f4b37cc357a109', '100001', 'news-category-finance-flash', 'em-202611263940994630-43d8dca138', '阿联酋迪拜航空将恢复迪拜至以色列特拉维夫航班', '当地时间11月26日自以色列方面获悉，阿联酋迪拜航空公司将于12月3日起恢复迪拜国际机场至以色列特拉维夫本-古里安国际机场的直飞航班，相关航班已开放预订。', 'published', NULL, FALSE, 100, 1, '2026-11-26T15:51:43Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-0432020585628eb5', '100001', 'news-category-finance-flash', 'em-202611263940993495-a746314f32', '瑞银承诺维持全球业务布局 回应瑞士议会委员会支持加码资本监管', '瑞银集团最高管理层本周致信员工，试图向他们保证，瑞士收紧监管的努力不会夺走该行历经数十年打造的成果 —— 一项真正意义上的全球化业务。员工备忘录显示，董事长Colm Kelleher和首席执行官Sergio Ermotti表示，该行仍“完全致力于我们的战略、增长目标和全球布局”。这份备忘录是对议会一个关键委员会周二投票结果的回应。该委员会支持将资本金要求提高160亿美元，这对瑞银而言是又一次挫折。瑞银的海外业务恰恰是瑞士政界人士关注的焦点，他们正试图防止2023年瑞信倒闭事件重演。拟议中的资本金要求瑞银以境内资本覆盖海外子公司几乎全部持股价值，这可能限制其海外业务增长。', 'published', NULL, FALSE, 100, 1, '2026-11-26T15:44:56Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-922a49125b89d7d2', '100001', 'news-category-finance-flash', 'em-202611263940994043-4bc9cb03d0', '中国驻欧盟使团发言人就欧洲议会通过涉区锦新案消极动议答记者问', '中国驻欧盟使团发言人就欧洲议会通过涉区锦新案消极动议答记者问。问：11月26日，欧洲议会就区锦新案判决通过消极动议。中方对此有何评论？', 'published', NULL, FALSE, 100, 1, '2026-11-26T15:41:55Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-1e841cd5bae9badf', '100001', 'news-category-finance-flash', 'em-202611263940989625-83d602a1cf', '美国据悉将推迟针对欧洲军事存在的改革', '美国据悉将推迟针对欧洲军事存在的改革。', 'published', NULL, FALSE, 100, 1, '2026-11-26T15:36:24Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-04835c5e6af81ea8', '100001', 'news-category-finance-flash', 'em-202611263940986341-715b93636c', '欧盟委员会的会议议程显示：12月15日的会议可能就特斯拉的辅助驾驶系统进行投票', '欧盟委员会的会议议程显示，12月15日的会议可能就特斯拉的辅助驾驶系统进行投票。', 'published', NULL, FALSE, 100, 1, '2026-11-26T15:27:20Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-a792c54ea0c73657', '100001', 'news-category-finance-flash', 'em-202611263940979677-92ea345825', '乌克兰称其在夜间袭击了俄罗斯的斯拉维扬斯克炼油厂', '乌克兰称其在夜间袭击了俄罗斯的斯拉维扬斯克炼油厂。', 'published', NULL, FALSE, 100, 1, '2026-11-26T15:18:38Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-6881e09a195f555d', '100001', 'news-category-finance-flash', 'em-202611263940979214-e676d0e4a9', '星图测控：被禁止参加军事航天部队采购活动2年', '星图测控公告，军采网于2026年11月26日发布处理公告，军事航天部队采购管理部门决定自2026年7月14日至2028年7月14日期间禁止公司参加相应范围军队物资工程服务采购活动。本次违规处理的串标事项预计将对公司的经营产生一定影响，公司为军事航天部队及其下属单位提供的业务多集中在定制化开发项目，即公司依托自身技术结合用户航天任务的差异化需求，为其提供航天测控管理、航天数字仿真等业务的定制化系统开发与服务。公司最终用户为军事航天部队及其下属单位的受影响合同金额约占年度预计营业收入的20%-22%。', 'published', NULL, FALSE, 100, 1, '2026-11-26T15:16:28Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-a9e78f961736118c', '100001', 'news-category-finance-flash', 'em-202611263940974221-d33e5ab6b8', '以色列正直党与民主党就双边组阁协议达成一致', '当地时间26日，以色列正直党和以色列民主党发表联合声明，称两党已经就双边组阁协议达成共识。以色列民主党由此成为继“以色列是我们的家园”党之后，第二个与正直党敲定组阁协议的反对派阵营政党。', 'published', NULL, FALSE, 100, 1, '2026-11-26T15:08:21Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-5f76e5db2516c00e', '100001', 'news-category-finance-flash', 'em-202611263940972248-6033362727', '国内商品期市夜盘收盘涨跌参半 油脂油料涨幅居前', '国内商品期市夜盘收盘涨跌参半，油脂油料涨幅居前，CZCE菜粕涨2.01%；能源品多数上涨，INE低硫燃料油涨0.84%；黑色系多数上涨，DCE焦煤涨0.80%；农副产品全部上涨，CZCE白糖涨0.62%；化工品跌幅居前，SHFE丁二烯橡胶跌1.64%；非金属建材多数下跌，DCE PVC跌0.22%。', 'published', NULL, FALSE, 100, 1, '2026-11-26T15:01:18Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-177a882932e371e2', '100001', 'news-category-finance-flash', 'em-202611263940969891-4d9b1220b3', '国内部分商品期货夜盘收盘 主力合约涨多跌少', '截至23:00，国内部分商品期货夜盘收盘，主力合约涨多跌少。涨幅方面，乙二醇、菜粕涨超2%，短纤、菜油涨超1%；跌幅方面，铁矿石跌超2%，丁二烯胶、纯碱、苯乙烯跌超1%。', 'published', NULL, FALSE, 100, 1, '2026-11-26T15:00:16Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-3604cb4723cb693b', '100001', 'news-category-finance-flash', 'em-202611263940972143-95da0f9d57', '伊拉克石油部长表示：伊拉克10月的石油收入达到88亿美元', '伊拉克石油部长表示，伊拉克10月的石油收入达到88亿美元。石油出口量已从每日20万桶提升至每日360万桶。', 'published', NULL, FALSE, 100, 1, '2026-11-26T14:58:40Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-23a71cd193641abf', '100001', 'news-category-finance-flash', 'em-202611263940969140-c9e88e63e7', '特朗普表示：希望看到俄罗斯总统普京撤回其在欧洲各地的一切军事行动', '特朗普表示，希望看到俄罗斯总统普京撤回其在欧洲各地的一切军事行动。', 'published', NULL, FALSE, 100, 1, '2026-11-26T14:55:53Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-048eb14216a94290', '100001', 'news-category-finance-flash', 'em-202611263940970038-203318f544', '哈马斯谴责以方持续违反停火协议 正与巴各派别磋商应对措施', '当地时间26日，巴勒斯坦伊斯兰抵抗运动（哈马斯）政治局领导人哈亚发表声明，谴责以色列方面持续违反加沙停火协议并针对巴勒斯坦民众发动军事袭击。哈亚在声明中表示，在现有加沙停火协议框架下，巴方绝不接受“杀戮与封锁”并存的局面。他同时批评美国支持设立的所谓加沙“和平委员会”及相关协议担保方对以方行为保持沉默，称这种态度“不可接受”。', 'published', NULL, FALSE, 100, 1, '2026-11-26T14:52:15Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-af4c1ea957a50cfc', '100001', 'news-category-finance-flash', 'em-202611263940964385-75f6230e69', '沙特牵头的联军表示：胡塞武装袭击了吉赞炼油厂', '沙特牵头的联军表示，胡塞武装袭击了吉赞炼油厂。', 'published', NULL, FALSE, 100, 1, '2026-11-26T14:48:22Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-581937846a41e947', '100001', 'news-category-finance-flash', 'em-202611263940961471-47dd16338d', '汇丰银行将惠普评级从买入下调至持有；目标价从33.4美元下调至29.4美元', '汇丰银行将惠普评级从买入下调至持有；目标价从33.4美元下调至29.4美元。', 'published', NULL, FALSE, 100, 1, '2026-11-26T14:44:25Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-5976ee68ba039244', '100001', 'news-category-finance-flash', 'em-202611263940958777-bd7031ce5b', '保加利亚对银行和保险公司征收税率为33%的一次性暴利税', '保加利亚对银行和保险公司征收税率为33%的一次性暴利税。', 'published', NULL, FALSE, 100, 1, '2026-11-26T14:41:54Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-e19a7b1a071e3d24', '100001', 'news-category-finance-flash', 'em-202611263940956693-3e668627d7', '俄罗斯表示：其在敖德萨附近的黑海击中了一艘货船', '俄罗斯表示，其在敖德萨附近的黑海击中了一艘货船。', 'published', NULL, FALSE, 100, 1, '2026-11-26T14:39:27Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-f63fddb6a2a33dc6', '100001', 'news-category-finance-flash', 'em-202611263940954189-46e3eb9d08', '厄尔尼诺相关降雨灾害已致厄瓜多尔28人死亡', '当地时间11月25日凌晨，受持续强降雨影响，厄瓜多尔洛斯里奥斯省莫卡切地区发生山体滑坡。据悉，此次灾害已造成2人死亡、1人受伤，另有1名未成年人失踪。当地政府宣布进入紧急状态，并要求部分位于高风险区域的居民撤离。厄瓜多尔国家风险管理秘书处25日发布报告显示，自今年8月29日以来，与厄尔尼诺现象相关的降雨灾害已波及该国24个省，累计造成28人死亡、15人受伤，超12万人受到影响。', 'published', NULL, FALSE, 100, 1, '2026-11-26T14:33:41Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-7c21e44700b027ad', '100001', 'news-category-finance-flash', 'em-202611263940954067-9f2bd81d2c', '四大商业银行已与上市公司签订股票回购增持贷款合同超6000亿元', '记者26日从工商银行等商业银行了解到，在中国人民银行近日会同金融监管总局、中国证监会等部门明确将股票回购增持再贷款政策由阶段性安排转为长期制度性安排，并进一步下调再贷款利率之后，工商银行、农业银行、中国银行、建设银行等多家银行迅速落实有关部署，加大股票回购增持贷款投放力度。', 'published', NULL, FALSE, 100, 1, '2026-11-26T14:31:45Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-ab5399eb98b75ef3', '100001', 'news-category-finance-flash', 'em-202611263940953763-ecbc1b70cb', '多伦多股票指数开盘上涨124.78点', '多伦多股票指数开盘上涨124.78点，或0.37%，至34,304.77点。', 'published', NULL, FALSE, 100, 1, '2026-11-26T14:31:32Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-ae188ccdca220316', '100001', 'news-category-finance-flash', 'em-202611263940952117-640a9c6ae4', '特朗普敦促对美国GDP数据的修正展开调查', '特朗普敦促对美国GDP数据的修正展开调查。', 'published', NULL, FALSE, 100, 1, '2026-11-26T14:27:58Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-4f7c61abf6d6bf99', '100001', 'news-category-finance-flash', 'em-202611263940951484-9f73992133', '美国总统特朗普：讨论了俄乌避免扩大战事的重要性', '美国总统特朗普表示，讨论了俄乌避免扩大战事的重要性。', 'published', NULL, FALSE, 100, 1, '2026-11-26T14:25:40Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-3ceb6090c54dd573', '100001', 'news-category-finance-flash', 'em-202611263940951830-cfbd13442f', '中国驻尼泊尔大使馆提醒中国公民切实防范电诈风险', '中国驻尼泊尔大使馆提醒广大中国公民：提高安全防范意识，务必高度警惕网络“高薪招聘”等各类诈骗陷阱，谨防上当受骗。', 'published', NULL, FALSE, 100, 1, '2026-11-26T14:24:24Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-26708e8acae43e93', '100001', 'news-category-finance-flash', 'em-202611263940951927-d262c95566', '茅台集团总经理王莉与贵州爱茅台数科公司技术人员交流座谈', '据贵州茅台消息，11月25日，茅台集团党委副书记、总经理王莉与贵州爱茅台数字科技有限公司技术人员交流座谈。', 'published', NULL, FALSE, 100, 1, '2026-11-26T14:24:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-f88f7e6a593a8247', '100001', 'news-category-finance-flash', 'em-202611263940945620-b7401af880', 'AI 应用进入下半场 投资人开始冷静算账', '冰箱贴机器人、咖啡机器人、地铁指引机器人、分拣机器人……AI技术进入更多生产生活场景，商业化也在提速。文投会路演现场，多位投资人表示，AI技术的竞争已进入下半场，落地应用成为关键词，而到了这个阶段，投资人关心的已经不是机器人能做什么动作，而是项目商业模式能否跑通，多久能回本。', 'published', NULL, FALSE, 100, 1, '2026-11-26T14:18:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-6673eff4e1011fed', '100001', 'news-category-finance-flash', 'em-202611263940929815-6e3ba99277', '全球基金于26日净买入金额达584亿卢比的印度股票', '全球基金于26日净买入金额达584亿卢比的印度股票。', 'published', NULL, FALSE, 100, 1, '2026-11-26T14:08:03Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-78cc60b5a71b78c7', '100001', 'news-category-finance-flash', 'em-202611263940918925-2453939ed5', '以防长：若哈马斯不解除武装将驱离100万加沙居民', '以色列国防部长卡茨26日在社交媒体发表声明称，如果哈马斯不解除武装，以色列国防军将继续发动军事行动，并驱离100万加沙地带居民。', 'published', NULL, FALSE, 100, 1, '2026-11-26T14:04:55Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-5ba98040f7ddcdcd', '100001', 'news-category-finance-flash', 'em-202611263940910716-c420a75a40', '中国神华：董事会批准根据一般性授权发行H股方案', '中国神华(601088.SH)公告称，公司董事会选举张长岩为第六届董事会董事长及法定代表人，同时批准根据一般性授权发行H股方案，根据市场情况及公司实际需要，在本议案确定的发行规模、定价方式、发行对象、募集资金用途等范围内，决定本次授权发行的具体实施时间、最终发行数量、发行价格、募集资金规模、发行对象及其他配售安排。', 'published', NULL, FALSE, 100, 1, '2026-11-26T14:01:54Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-7a4a6400356e6f94', '100001', 'news-category-finance-flash', 'em-202611263940908826-f3c0a15b16', '宝马计划在德国提供更多离职补偿方案 聚焦拟裁撤岗位', '宝马计划未来几个月在德国向更多员工提供离职补偿协议，这一次将针对具体拟裁撤岗位。宝马确认，其员工重组计划已于11月完成，并提前实现目标。', 'published', NULL, FALSE, 100, 1, '2026-11-26T14:01:21Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-21bdb03cd05f8ff3', '100001', 'news-category-finance-flash', 'em-202611263940909420-fc811135a4', '位于俄罗斯克拉斯诺达尔边疆区的斯拉维扬斯克-ECO炼油厂在遭到无人机袭击后发生火灾', '位于俄罗斯克拉斯诺达尔边疆区的斯拉维扬斯克-ECO炼油厂在遭到无人机袭击后发生火灾。', 'published', NULL, FALSE, 100, 1, '2026-11-26T14:00:03Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-90da410f33ac07fa', '100001', 'news-category-finance-flash', 'em-202611263940905188-89acf33252', '协创数据：控股子公司光模块产品已通过国家级超算中心验证并实现交付', '协创数据(300857.SZ)发布投资者关系活动记录表公告，公司控股子公司光为科技已形成200G/400G/800G/1.6T全系列高速光模块产品矩阵，部分产品已通过国家级超算中心验证并实现交付。', 'published', NULL, FALSE, 100, 1, '2026-11-26T13:55:49Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-2f831c475b3fba3b', '100001', 'news-category-finance-flash', 'em-202611263940900615-c5cce6eb96', '华为乾崑、宁德时代巧克力换电推出智能补能解决方案', '在2026华为乾崑生态大会上，华为乾崑与宁德时代巧克力换电公布合作成果：双方将打通高阶智驾与换电生态，推出智能补能解决方案。', 'published', NULL, FALSE, 100, 1, '2026-11-26T13:53:22Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-647113620a36acff', '100001', 'news-category-finance-flash', 'em-202611263940897845-baf69dd3cf', '中国儒意称董事会已通过授权公司进行股份回购 金额最高为5亿港元', '中国儒意称董事会已通过授权公司进行股份回购，金额最高为5亿港元。', 'published', NULL, FALSE, 100, 1, '2026-11-26T13:52:38Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-7227b99e8db64d9d', '100001', 'news-category-finance-flash', 'em-202611263940894141-4c0772fcbf', '全国流感处于中流行水平 检测阳性率上升 中疾控发布提示', '中国疾控中心今天（26日）发布的11月16日—11月22日全国急性呼吸道传染病哨点监测情况显示，当前，全国流感活动整体处于中流行水平，南、北方省份流感病毒检测阳性率上升。全国检出流感阳性样本中，A（H1N1）pdm09占比65.0%、A（H3N2）占比9.7%，B（Victoria）系占比25.3%。5—14岁病例组检测阳性率高于其他年龄组。', 'published', NULL, FALSE, 100, 1, '2026-11-26T13:48:31Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-00c2155aefd61849', '100001', 'news-category-finance-flash', 'em-202611263940891091-f4afdc267e', '汇丰控股：现在断言金价跌势止步还为时过早 但抛售可能有限', '汇丰控股表示，现在断言金价跌势止步还为时过早，但抛售可能有限。', 'published', NULL, FALSE, 100, 1, '2026-11-26T13:46:56Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-0d414a707c60026b', '100001', 'news-category-finance-flash', 'em-202611263940890891-8550d7848c', '中国首例无线侵入式汉语脑机接口临床试验完成 让渐冻症患者“开口说话”', '复旦大学科研团队2026年11月26日发布了脑机接口的里程碑新突破：成功开展了中国首例无线侵入式汉语脑机接口临床试验，让渐冻症患者实现了“靠意念就能交流”。', 'published', NULL, FALSE, 100, 1, '2026-11-26T13:45:11Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-7d3c3ff47be14799', '100001', 'news-category-finance-flash', 'em-202611263940884513-79888c2c90', 'OPEC+据悉很可能将在周日的会议上把石油产量目标至少延续到2027年第一季度不变', 'OPEC+据悉很可能将在周日的会议上把石油产量目标至少延续到2027年第一季度不变。', 'published', NULL, FALSE, 100, 1, '2026-11-26T13:41:52Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-42c3e19c74cb6544', '100001', 'news-category-finance-flash', 'em-202611263940885814-f49b384ae7', '英国两年期国债收益率上升8个基点至4.86%', '英国两年期国债收益率上升8个基点至4.86%。', 'published', NULL, FALSE, 100, 1, '2026-11-26T13:41:35Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-3d0c7d74985225b5', '100001', 'news-category-finance-flash', 'em-202611263940881218-59c26d5eef', '德国选择党联合主席：资助乌克兰阻碍和平', '当地时间11月25日，德国总理默茨在德国联邦议院发言表示，支持乌克兰就是在支持德国自己。德国选择党联合主席爱丽丝·魏德尔则反驳道，对乌克兰的军事支持，每年让德国纳税人承担数额巨大的开支，这些钱本可以在别处办成很多事。此外，她指出，对乌克兰的资助不仅无助于结束战争，反而成了实现和平的障碍。', 'published', NULL, FALSE, 100, 1, '2026-11-26T13:37:05Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-da1a3751ee78b4b1', '100001', 'news-category-finance-flash', 'em-202611263940878356-5c394ae811', '北京多家医院已落地手术机器人', '北京市卫生健康委副主任陈航11月26日在新闻发布会会上介绍，据统计，目前北京市已累计获批45个医用手术机器人注册证，数量居全国首位。', 'published', NULL, FALSE, 100, 1, '2026-11-26T13:36:16Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-63c6a847c8e9dbe9', '100001', 'news-category-finance-flash', 'em-202611263940877740-a5a532751b', '据报道 国际清算银行总经理德科斯将出任下一任欧洲央行行长', '据报道，国际清算银行总经理德科斯将出任下一任欧洲央行行长。', 'published', NULL, FALSE, 100, 1, '2026-11-26T13:30:51Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-d189274b509ed2aa', '100001', 'news-category-finance-flash', 'em-202611263940862894-291775696a', '我国科研团队研制出新型智能纤维 识别准确率100%', '据中国科学技术大学消息，该校教授傅尧团队面向具身智能与绿色可持续发展的双重需求，创制出兼具高强韧性、稳定离子传导和低泄漏特征的生物基智能纤维，并融合深度学习实现复杂人体动作的精准识别，为发展绿色、高性能智能感知材料提供了新思路。相关成果近日在线发表于学术期刊《先进材料》。', 'published', NULL, FALSE, 100, 1, '2026-11-26T13:28:02Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-257bcd9ed9379d42', '100001', 'news-category-finance-flash', 'em-202611263940858522-b99987ce18', '巴西股市上涨3.4% 创10月5日以来最大单日涨幅', '巴西股市上涨3.4%，创10月5日以来最大单日涨幅，因财政部长乐观情绪提振。', 'published', NULL, FALSE, 100, 1, '2026-11-26T13:23:55Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-4af4e47eb9b8de9b', '100001', 'news-category-finance-flash', 'em-202611263940857510-2c3aa2a381', '巴西雷亚尔兑美元涨幅扩大至1.2%', '巴西雷亚尔兑美元涨幅扩大至1.2%。', 'published', NULL, FALSE, 100, 1, '2026-11-26T13:19:56Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-d365e5ab5570a066', '100001', 'news-category-finance-flash', 'em-202611263940857617-bad83c5536', '中恒集团与修正集团达成战略合作', '据中恒集团消息，近日，中恒集团与修正药业集团股份有限公司（简称“修正集团”）正式达成产品合作，双方围绕多款优质中成药品种展开深度协同。', 'published', NULL, FALSE, 100, 1, '2026-11-26T13:19:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-8044495072132387', '100001', 'news-category-finance-flash', 'em-202611263940857476-77ea925fb4', '英国和欧盟尚未就退出新协议的惩罚性费用达成一致', '英国和欧盟尚未就退出新协议的惩罚性费用达成一致。', 'published', NULL, FALSE, 100, 1, '2026-11-26T13:16:11Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-fb3242f7be70369c', '100001', 'news-category-finance-flash', 'em-202611263940845988-00b2e3504d', '水利部：加快构建覆盖农业、工业、城镇生活等主要用水领域的用水定额管理体系', '水利部党组书记、部长李国英11月26日主持召开部务会议，审议《用水定额管理办法》，研究青藏高原冰湖监测预警及风险防范有关工作。会议强调，要严格落实生态环境法典、水法等法律要求，加快构建覆盖农业、工业、城镇生活等主要用水领域的用水定额管理体系，建立定额实施定期评估和动态更新机制，强化定额刚性约束作用，以用水定额管理制度落实促进用水方式改进优化，提升水资源集约安全利用水平。', 'published', NULL, FALSE, 100, 1, '2026-11-26T13:12:06Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-ef756741c1572fdd', '100001', 'news-category-finance-flash', 'em-202611263940830127-87cf4309f0', '英国皇家海军总部遭疑似炸弹威胁', '今天（11月26日），位于英国南部港口城市朴次茅斯的英国皇家海军总部遭遇疑似炸弹威胁，警方紧急赶赴现场。英国皇家海军发言人证实，警方及英国国防部人员正在处理一起安全事件，并呼吁公众暂时避开事发区域。', 'published', NULL, FALSE, 100, 1, '2026-11-26T13:01:55Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-d02011e9ac6c5102', '100001', 'news-category-finance-flash', 'em-202611263940827683-990d2e10c7', '我国发布全球首个高效灵活燃煤发电技术', '今天，我国自主研发的全球首个新型高效灵活燃煤发电技术成功发布，多项核心指标达到国际领先水平。', 'published', NULL, FALSE, 100, 1, '2026-11-26T13:00:31Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-2b92c76a61a5495f', '100001', 'news-category-finance-flash', 'em-202611263940827464-c48d511178', '国内商品期货夜盘开盘 主力合约几乎全线上涨', '国内商品期货夜盘开盘，主力合约几乎全线上涨。涨幅方面，沪银涨近4%，乙二醇涨近3%，沪锌、沪镍、沪锡涨超2%，燃油、短纤涨近2%，焦煤、低硫燃油、塑料、沪铅、沪金等涨超1%；跌幅方面，LPG、氧化铝、纯碱、豆一、铁矿石小幅下跌。', 'published', NULL, FALSE, 100, 1, '2026-11-26T13:00:07Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-2e063a8108a4ae8f', '100001', 'news-category-finance-flash', 'em-202611263940829283-c183791ed2', '波罗的海干散货运价指数涨1.45%', '波罗的海干散货运价指数涨1.45%，至3152点。', 'published', NULL, FALSE, 100, 1, '2026-11-26T13:00:04Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-63833e708ee26c2c', '100001', 'news-category-finance-flash', 'em-202611263940829197-88dd613375', '启境汽车发布全新品牌LOGO', '11月26日，启境汽车发布全新品牌LOGO标识。', 'published', NULL, FALSE, 100, 1, '2026-11-26T12:58:28Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-3a0fc9e75e417b92', '100001', 'news-category-finance-flash', 'em-202611263940824322-24994b2438', '北京“十五五”期间将支持更多“全球新”药械研发上市', '北京市政府新闻办11月26日举行“首都开局起步‘十五五’”系列主题新闻发布会。北京市药品监督管理局局长曹巍在回答新京报记者提问时透露，“十五五”时期，北京将支持更多“全球新”药械研发上市。', 'published', NULL, FALSE, 100, 1, '2026-11-26T12:53:16Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-28e8c47cf2614f99', '100001', 'news-category-finance-flash', 'em-202611263940822858-a0fc52643d', '三星电子拟引入机器人“造芯” 已成立专门团队 预计年内敲定合作方', '三星电子计划在其半导体工厂部署机器人。韩媒今日报道称，三星电子设备解决方案（DS）事业部已成立并运营一支“机器人团队”，该团队隶属于DS部全球制造与基础设施总部，由副总裁李锡元担任负责人，旨在推进机器人技术在半导体工厂中的实际应用。按照规划，三星将在年内敲定机器人合作厂商，明年开展技术评估，2028年正式投入产线。', 'published', NULL, FALSE, 100, 1, '2026-11-26T12:51:11Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-f7d38ffb3a07fa5a', '100001', 'news-category-finance-flash', 'em-202611263940821879-acb1a0a1e1', '北京拟用三年建成200个中小企业营商环境服务站点', '北京市十六届人大常委会第二十七次会议听取市政府关于北京市中小企业发展情况的书面报告。北京将在中小企业集聚、创新活跃的街道和乡镇试点建设营商环境服务站点，由街镇专职人员牵头、专业团队提供支持，就近对接企业需求。按照计划，北京将用三年时间打造200个示范站点，为中小企业建设“15分钟服务圈”。', 'published', NULL, FALSE, 100, 1, '2026-11-26T12:51:05Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-f65fe986df91718b', '100001', 'news-category-finance-flash', 'em-202611263940818135-be057a9dbd', '六福集团：中期盈利7.12亿港元 同比增加15%', '六福集团(00590.HK)发布截至2026年9月30日止6个月中期业绩，该集团取得收入81.95亿港元，同比增加19.8%；净利润7.12亿港元，同比增加15%。', 'published', NULL, FALSE, 100, 1, '2026-11-26T12:46:16Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-4078c0def8b4d619', '100001', 'news-category-finance-flash', 'em-202611263940817240-e6863ca2b6', '威海市人民政府与山东黄金集团签署战略合作协议', '据“威海发布”消息，11月26日，威海市人民政府与山东黄金集团签署战略合作协议。威海市委书记张海波说，山东黄金集团是威海重要的合作伙伴，本次签约涉及经贸合作、矿产开发、资源整合、绿色智能采选、装备配套等领域，必将有效发挥双方优势，推动威海黄金产业实现更大突破。', 'published', NULL, FALSE, 100, 1, '2026-11-26T12:43:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-73b51db9de684590', '100001', 'news-category-finance-flash', 'em-202611263940815392-108c73bd8d', '印度国家证券交易所（NSE）获得印度储备银行批准推出公司债券指数期货', '印度国家证券交易所（NSE）获得印度储备银行批准推出公司债券指数期货。', 'published', NULL, FALSE, 100, 1, '2026-11-26T12:42:20Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-d044743f80306668', '100001', 'news-category-finance-flash', 'em-202611263940815073-b64b4b8ec4', '渣打旗下加密资产托管公司发生数据泄露', '渣打集团旗下加密资产托管子公司Zodia Custody Ltd.表示，公司发生安全事件，导致部分客户和员工信息泄露。Zodia Custody首席执行官Richard Clark在声明中表示，未经授权的一方入侵公司平台，并能够访问“有限的客户信息，包括可公开获取的机构资料，以及少数客户和员工的业务联系人姓名和电子邮件地址”。', 'published', NULL, FALSE, 100, 1, '2026-11-26T12:42:15Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-366bd70497705576', '100001', 'news-category-finance-flash', 'em-202611263940814067-9a5c28ea44', 'SAP与planqc深化量子计算合作 计划2027年在真实量子硬件上测试商业场景', '德国软件巨头SAP宣布扩大与德国量子计算公司planqc的合作，双方首次展示了如何将planqc的中性原子量子计算机集成至SAP软件环境。双方计划从2027年开始，在planqc真实量子硬件上测试初步商业应用场景。', 'published', NULL, FALSE, 100, 1, '2026-11-26T12:36:25Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-4ab5107740dedc53', '100001', 'news-category-finance-flash', 'em-202611263940811358-b4a112d291', '香港10月出口同比上升65.6%', '香港特区政府统计处26日发布的对外商品贸易统计数字显示，受人工智能相关电子产品出口的强劲增长带动，2026年10月香港整体出口货值达7645亿港元，同比增长65.6%，增速进一步加快。', 'published', NULL, FALSE, 100, 1, '2026-11-26T12:35:38Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-5f9e9b53676ce4cc', '100001', 'news-category-finance-flash', 'em-202611263940811141-b61875da04', '欧洲央行会议纪要：除非通胀前景“显著”改善 否则仍需加息', '欧洲央行会议纪要显示，除非通胀前景“显著”改善，否则仍需加息。', 'published', NULL, FALSE, 100, 1, '2026-11-26T12:34:59Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-39be68c1b2ad7628', '100001', 'news-category-finance-flash', 'em-202611263940810783-a98f0d75b5', '欧洲央行会议纪要：不确定性依然高企 能源冲击对通胀的全面影响尚未显现', '欧洲央行会议纪要显示，不确定性依然高企，能源冲击对通胀的全面影响尚未显现。', 'published', NULL, FALSE, 100, 1, '2026-11-26T12:31:39Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-49f6a7710ab7894e', '100001', 'news-category-finance-flash', 'em-202611263940811041-6da99d65ef', '国金证券：注销已回购股份1739.96万股', '国金证券(600109.SH)公告称，公司本次注销已回购股份17,399,600股，占注销前公司总股本的0.4724%。本次注销完成后，公司总股本由3,683,262,908股减少至3,665,863,308股。回购股份注销日为2026年11月27日。', 'published', NULL, FALSE, 100, 1, '2026-11-26T12:30:31Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-23ae56a75332b9dd', '100001', 'news-category-finance-flash', 'em-202611263940810671-039cd5a0d8', '国内首台16兆瓦级燃气轮机 顺利通过中国机械工业联合会组织的产品鉴定', '哈电集团汽轮机公司自主研制的国内首台16兆瓦级燃气轮机（HGT16），11月24日顺利通过中国机械工业联合会组织的产品鉴定，标志着该机组具备商业化应用条件，我国中小型自主燃气轮机领域再添大国重器。', 'published', NULL, FALSE, 100, 1, '2026-11-26T12:30:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-f6a95af4bb493593', '100001', 'news-category-finance-flash', 'em-202611263940809190-7eed2626e6', '荣盛发展：拟与平安信托进行债务重组 涉及债务本金9.29亿元', '荣盛发展(002146.SZ)公告称，公司子公司蚌埠荣盛锦业作为债务人，与平安信托存续债务本金9.29亿元。各方拟签署协议，若子公司提供担保，平安信托豁免债务本金0.5亿元；若平安信托通过公开挂牌完成债权转让，受让方同意豁免债务本金2亿元，公司需承担上限为1亿元的债权补偿。本次交易尚需提交公司股东会及平安信托受益人大会审议通过后方可生效。', 'published', NULL, FALSE, 100, 1, '2026-11-26T12:25:09Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-d66c0c74327a8d73', '100001', 'news-category-finance-flash', 'em-202611263940810359-b59c832d5f', '农业银行已与近200家上市公司达成合作意向 签订股票回购增持贷款合同超1500亿元', '据农业银行消息，近期，中国人民银行会同金融监管总局、中国证监会等部门召开股票回购增持再贷款座谈会，部署优化股票回购再贷款机制，明确将阶段政策转为长期制度性安排。截至目前，农业银行已与近200家上市公司达成合作意向，签订股票回购增持贷款合同超1500亿元。', 'published', NULL, FALSE, 100, 1, '2026-11-26T12:25:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-623514a6ad259b8f', '100001', 'news-category-finance-flash', 'em-202611263940806066-fc7e395f50', '瑜欣电子：拟1.6亿元收购光通信高精密光学元件公司华腾光电93.02%股权', '瑜欣电子(301107.SZ)公告称，公司董事会审议通过现金收购三明华腾光电科技有限公司93.02%股权的议案，交易金额1.6亿元。目标公司主要从事光通信领域高精密光学元件、器件的研发、生产、组装和销售，配套形成“光学毛坯—元件加工—精密镀膜—器件组装”全产业链自研自产模式。', 'published', NULL, FALSE, 100, 1, '2026-11-26T12:19:29Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-18fd0836d8fad8d1', '100001', 'news-category-finance-flash', 'em-202611263940806435-7797461dbb', '欧洲投资银行与南非计划签署3亿欧元矿产协议', '欧洲投资银行一名官员称，欧洲投资银行与南非最大开发金融机构计划合作，最高提供3亿欧元融资，用于撒哈拉以南非洲的关键矿产开采。该官员表示，这家欧洲多边开发银行与南非工业发展公司达成的合作，还将支持矿产加工环节的投资。', 'published', NULL, FALSE, 100, 1, '2026-11-26T12:18:19Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-b85e2e6440e75489', '100001', 'news-category-finance-flash', 'em-202611263940806548-2c28b946a4', '奇安信与恒舟驭远达成战略合作', '据奇安信集团消息，11月26日，奇安信集团与北京恒舟驭远航天科技有限公司（以下简称“恒舟驭远”）签署战略合作协议，围绕运载火箭研制全流程的信息安全建设展开长期合作。', 'published', NULL, FALSE, 100, 1, '2026-11-26T12:17:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-bb01a570df40184a', '100001', 'news-category-finance-flash', 'em-202611263940803456-2523dbf6be', '裕太微：向特定对象发行A股股票申请获上交所审核通过', '裕太微(688515.SH)公告称，公司于2026年11月26日收到上交所出具的审核意见，公司向特定对象发行股票申请符合发行条件、上市条件和信息披露要求。该事项尚需获得证监会同意注册的决定后方可实施，最终能否获得及时间存在不确定性。', 'published', NULL, FALSE, 100, 1, '2026-11-26T12:14:57Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-ebde2c41dfc2f4a1', '100001', 'news-category-finance-flash', 'em-202611263940803320-4713b44735', '精测电子：控股子公司签订1.998亿元半导体前道量检测设备销售合同', '精测电子(300567.SZ)公告称，公司控股子公司上海精测近日与客户签订销售合同，拟出售半导体前道量检测设备，合同金额合计1.998亿元。', 'published', NULL, FALSE, 100, 1, '2026-11-26T12:14:19Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-131b5eab1f61ee25', '100001', 'news-category-finance-flash', 'em-202611263940801790-79e24870a1', '日本烟草据称正研究收购帝国品牌', '据报道，日本烟草（JapanTobacco）正在研究收购英国烟草公司帝国品牌（ImperialBrands）的交易。帝国品牌股价上涨6.4%。', 'published', NULL, FALSE, 100, 1, '2026-11-26T12:08:26Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-c1bd80c3650ee375', '100001', 'news-category-finance-flash', 'em-202611263940801651-ea0ecf5f84', '伦锌日内大涨4%', '伦锌日内大涨4%，现报3568.50美元/吨。', 'published', NULL, FALSE, 100, 1, '2026-11-26T12:08:13Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-5ba41aa3318374bc', '100001', 'news-category-finance-flash', 'em-202611263940800420-fa56480b3e', '6天3板襄阳轴承：部分精密轴承产品可用于谐波减速器等领域 截止目前累计营业收入仅20.52万元', '襄阳轴承(000678.SZ)公告称，公司股票连续3个交易日收盘价格涨幅偏离值累计达21.42%，属于异常波动。部分精密轴承产品可用于谐波减速器等领域，截止目前累计营业收入仅20.52万元，占比低，尚未盈利，业务存不确定性。', 'published', NULL, FALSE, 100, 1, '2026-11-26T12:07:02Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-3f37bdc4ade9b69b', '100001', 'news-category-finance-flash', 'em-202611263940795196-880f4a3b15', '中俄两军举行战略磋商', '11月26日，中俄两军以视频会议方式举行战略磋商。双方围绕落实两国元首共识、推动两军关系持续深化拓展进行交流，就国际和地区形势深入交换意见，表示两军将进一步加强沟通协作，共同维护国际和地区安全稳定。', 'published', NULL, FALSE, 100, 1, '2026-11-26T12:06:30Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-3700da302a97db14', '100001', 'news-category-finance-flash', 'em-202611263940799421-6e43d1b0e5', '巴西雷亚尔上涨0.8%', '巴西雷亚尔上涨0.8%，巴西总统卢拉试探特拉布科出任政府要职。', 'published', NULL, FALSE, 100, 1, '2026-11-26T12:06:19Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-3d0a0a12ab95dd22', '100001', 'news-category-finance-flash', 'em-202611263940800514-8e246fa314', '招商蛇口：拟向全资子公司南油公司增资190亿元', '招商蛇口(001979.SZ)公告称，公司拟以现金出资方式向全资子公司深圳市南油(集团)有限公司增资190亿元，资金来源为公司自有资金。本次增资旨在加强产权层级管控，提升内部管理与运营效能。', 'published', NULL, FALSE, 100, 1, '2026-11-26T12:05:03Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-4a619de88d38ab93', '100001', 'news-category-finance-flash', 'em-202611263940786992-cc845ba90c', '阿里加码北美招聘 Qwen团队今年已吸纳数百名AI人才', '阿里正在北美加大招聘力度，主要面向全球顶级AI研究员。目前，Qwen 北美团队已开放多个岗位，涉及模型研究、训练与推理、多模态、智能体（Agent）和数据等方向。今年全球已有数百人加入阿里Qwen大模型团队。', 'published', NULL, FALSE, 100, 1, '2026-11-26T12:02:55Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-bce050f0a403e889', '100001', 'news-category-finance-flash', 'em-202611263940784894-639d2652ab', '市场监管总局开展网络交易平台信用共治活动', '市场监管总局开展网络交易平台信用共治活动。推动平台企业守信践诺、规范经营，积极营造规范有序、诚信放心的网络消费环境。发布《网络交易平台信用共治倡议书》，向网络交易平台企业发出共同参与平台企业信用共治、将信用管理融入平台治理各环节的倡议。', 'published', NULL, FALSE, 100, 1, '2026-11-26T12:01:29Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-f1c5566850ff46c9', '100001', 'news-category-finance-flash', 'em-202611263940783233-ee6c2da7dd', '机构：Q3全球PC GPU出货量达到7280万颗 同比下降5%', 'Jon Peddie Research报告称，全球PC GPU出货量在2026年第三季度达到7280万颗，环比下降3.6%、同比下降5%。该数据在历年三季度通常会环比增长。从供应商角度，英特尔的PC GPU市场份额上升2.6个百分点、AMD与英伟达各下跌1.3%左右；英特尔出货量增长0.8%，另两家的跌幅在9%附近。', 'published', NULL, FALSE, 100, 1, '2026-11-26T12:01:09Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-3dcc45fd2a83d759', '100001', 'news-category-finance-flash', 'em-202611263940781319-39ac32da6a', '香港网约车驾驶许可证下周起接受申请', '香港特区政府运输署公布，网约车车辆驾驶许可证下周一上午10时起接受申请。合资格申请者届时可透过香港政府一站通网页提出网上申请。驾驶许可证数目不设上限，全年接受申请。', 'published', NULL, FALSE, 100, 1, '2026-11-26T12:00:24Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-047ef340cbb4a841', '100001', 'news-category-finance-flash', 'em-202611263940779995-e327d0ab5b', '上海国际能源交易中心：进一步拓展套利指令适用范围 适用品种包括低硫燃料油、集运指数（欧线）期货', '上海国际能源交易中心发布通知，为了满足市场需要，提高市场运行效率，自2026年12月7日（即2026年12月4日晚连续交易时段）起，上海国际能源交易中心将拓展套利指令适用品种。此次拓展的套利指令适用品种包括低硫燃料油、集运指数（欧线）期货。', 'published', NULL, FALSE, 100, 1, '2026-11-26T11:57:16Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-af56fabc9f86b77d', '100001', 'news-category-finance-flash', 'em-202611263940777444-e3a45e1881', '华为乾崑发布“星驰辅助驾驶” 2027年超10款车型量产上市', '华为公司高级副总裁、引望公司CEO靳玉志今日宣布推出“星驰辅助驾驶”，未来乾崑智驾面向自动驾驶，星驰辅助驾驶则专注于辅助驾驶。据其透露，2027年超10款车型将搭载星驰辅助驾驶量产上市，其中包括东风奕派、深蓝汽车、上汽通用五菱、广汽传祺、北汽极狐等。', 'published', NULL, FALSE, 100, 1, '2026-11-26T11:52:30Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-3b3d51fcbc903e9c', '100001', 'news-category-finance-flash', 'em-202611263940775162-58cfa3a4b1', '摩根大通将贵州茅台评级上调至超配 目标价1800元', '摩根大通证券股份有限公司将贵州茅台评级上调至超配，目标价1800元人民币，即上涨23%。摩根大通分析师Jessie Xu之前的评级为中性。', 'published', NULL, FALSE, 100, 1, '2026-11-26T11:50:13Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-1d566547f37b1a59', '100001', 'news-category-finance-flash', 'em-202611263940774984-9011708d71', '欧洲央行拉加德：人工智能是经济保持稳定的原因之一', '欧洲央行拉加德告诉欧盟领导人，人工智能是经济保持稳定的原因之一。', 'published', NULL, FALSE, 100, 1, '2026-11-26T11:46:33Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-12ced3f915bb5465', '100001', 'news-category-finance-flash', 'em-202611263940773490-cb1bd2f68d', '宁德时代称26日回购14.8万股A股股份 耗资约2999万元', '宁德时代称26日回购14.8万股A股股份，耗资约2999万元。', 'published', NULL, FALSE, 100, 1, '2026-11-26T11:44:58Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-a6f7375196c94ba4', '100001', 'news-category-finance-flash', 'em-202611263940773239-0f5fff09ee', '英国央行警告AI融资风险 大型科技公司债务及表外承诺超4万亿美元', '英国央行警告，人工智能投资热潮所需融资规模及覆盖范围持续扩大，可能加剧全球金融体系脆弱性。英国央行估计，大型科技公司的债务及表外承诺总额已超过4万亿美元。', 'published', NULL, FALSE, 100, 1, '2026-11-26T11:44:25Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-b7a6179192d904dd', '100001', 'news-category-finance-flash', 'em-202611263940771148-94082108de', '海亮股份：终止发行H股股票并在香港联交所主板上市', '海亮股份(002203.SZ)公告称，公司基于市场环境与自身发展规划的综合考量，经审慎决策，董事会同意终止发行H股股票并在香港联交所主板上市的相关事项。', 'published', NULL, FALSE, 100, 1, '2026-11-26T11:42:08Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-a391d34470c017ab', '100001', 'news-category-finance-flash', 'em-202611263940769673-12eaffe357', '英国银行股回吐部分涨幅 此前英国央行拟调整资本要求', '英国央行公布降低银行资本要求的新措施后，英国银行股一度扩大涨幅。拟议调整的力度小于游说团体UK Finance此前寻求的方案。不同银行的受益程度将有所不同，英国国内业务敞口较大的银行涨幅一度扩大至约3%，随后回吐大部分涨幅。', 'published', NULL, FALSE, 100, 1, '2026-11-26T11:34:58Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-e9b15087238e0416', '100001', 'news-category-finance-flash', 'em-202611263940769174-8296fa7a74', '纳指ETF富国(513870)将于2026年11月27日开市起至当日10:30停牌', '纳指ETF富国(513870)将于2026年11月27日开市起至当日10:30停牌。', 'published', NULL, FALSE, 100, 1, '2026-11-26T11:34:27Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-fe78978b74de4fae', '100001', 'news-category-finance-flash', 'em-202611263940768919-f619928843', '纳斯达克ETF华夏(513300)将于2026年11月27日开市起至当日10:30停牌', '纳斯达克ETF华夏(513300)将于2026年11月27日开市起至当日10:30停牌。', 'published', NULL, FALSE, 100, 1, '2026-11-26T11:34:24Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-2610b010cf927fed', '100001', 'news-category-finance-flash', 'em-202611263940769470-be670969e1', '纳指ETF国泰(513100)将于2026年11月27日开市起至当日10:30停牌', '纳指ETF国泰(513100)将于2026年11月27日开市起至当日10:30停牌。', 'published', NULL, FALSE, 100, 1, '2026-11-26T11:34:20Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-d9d92af3049c260f', '100001', 'news-category-finance-flash', 'em-202611263940769248-98d3788f2d', '全球芯片LOF(501225)将于2026年11月27日开市起至当日10:30停牌', '全球芯片LOF(501225)将于2026年11月27日开市起至当日10:30停牌。', 'published', NULL, FALSE, 100, 1, '2026-11-26T11:34:17Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-1191dc92b4342c8b', '100001', 'news-category-finance-flash', 'em-202611263940769364-d117beb911', '纳指ETF华泰柏瑞(513110)将于2026年11月27日开市起至当日10:30停牌', '纳指ETF华泰柏瑞(513110)将于2026年11月27日开市起至当日10:30停牌。', 'published', NULL, FALSE, 100, 1, '2026-11-26T11:34:14Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-003f5ae322f4e8d4', '100001', 'news-category-finance-flash', 'em-202611263940768839-1bdfe969a6', '迈威尔较高点回落60% 华尔街分析师接连大砍目标价', '迈威尔科技股价较6月高点已回落60%，华尔街分析师接连下调目标价。Oppenheimer分析师里克·谢弗11月24日将该股目标价从425美元下调至325美元，但维持“跑赢大盘”评级，新目标价仍隐含147%上行空间。', 'published', NULL, FALSE, 100, 1, '2026-11-26T11:33:48Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-1b61db4090d7ce3b', '100001', 'news-category-finance-flash', 'em-202611263940768741-45a2266ec8', '乌克兰军方：其打击了位于俄罗斯巴什科尔托斯坦的石油储罐', '乌克兰军方表示，其打击了位于俄罗斯巴什科尔托斯坦的石油储罐。', 'published', NULL, FALSE, 100, 1, '2026-11-26T11:33:05Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-9531590027859942', '100001', 'news-category-finance-flash', 'em-202611263940769717-d83bbef021', '宋城演艺：拟1亿元至1.5亿元回购股份用于注销', '宋城演艺(300144.SZ)公告称，公司拟使用自有资金以集中竞价方式回购股份，回购资金总额不低于1亿元且不超过1.5亿元，回购价格不超过8元/股。回购股份将全部用于注销并减少注册资本，回购期限为股东会审议通过之日起6个月内。', 'published', NULL, FALSE, 100, 1, '2026-11-26T11:32:41Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-0950f734bfd4f2e7', '100001', 'news-category-finance-flash', 'em-202611263940768634-1883d4af57', '纳指100ETF博时(513390)将于2026年11月27日开市起至当日10:30停牌', '纳指100ETF博时(513390)将于2026年11月27日开市起至当日10:30停牌。', 'published', NULL, FALSE, 100, 1, '2026-11-26T11:32:39Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-cac27e26e9c9171e', '100001', 'news-category-finance-flash', 'em-202611263940755053-66ae7a9ea7', '鼎龙股份：拟3000万元至5000万元回购公司股份', '鼎龙股份(300054.SZ)公告称，公司拟使用自有资金或自筹资金以集中竞价交易方式回购公司股份，回购资金总额不低于3000万元且不超过5000万元，回购价格不超过87.50元/股。', 'published', NULL, FALSE, 100, 1, '2026-11-26T11:29:10Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-bc207b22d4b7c689', '100001', 'news-category-finance-flash', 'em-202611263940755466-3bc19903cc', '拜耳拟投资最高5亿欧元扩建北京生产基地 预计2032年投产', '德国拜耳集团宣布，计划投资最高5亿欧元扩建其北京药品生产供应中心，这将成为拜耳迄今在中国最大的单笔制药投资。扩建项目位于北京经济技术开发区现有生产基地，规划建筑面积约1.8万平方米，设有三个可独立运营的生产模块，预计最早于2032年投产。项目计划新增最多300个工作岗位。', 'published', NULL, FALSE, 100, 1, '2026-11-26T11:28:09Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-c9841e487f7aa8da', '100001', 'news-category-finance-flash', 'em-202611263940753956-030335209a', '李强会见亚洲开发银行行长神田真人', '11月26日下午，国务院总理李强在北京人民大会堂会见亚洲开发银行行长神田真人。', 'published', NULL, FALSE, 100, 1, '2026-11-26T11:26:21Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-49aa30cbd253da73', '100001', 'news-category-finance-flash', 'em-202611263940754171-9101dbfc81', '泰胜风能：拟设立全资子公司并投资建设国际海工基地项目', '泰胜风能(300129.SZ)公告称，公司拟对全资子公司扬州泰胜风能装备有限公司增资1.2亿元，并由其在江苏扬州设立泰胜风能海工装备(江苏)有限公司，注册资本2.5亿元。同时，公司拟投资建设泰胜国际海工基地项目，投资总额不超过8.43亿元，主要生产出口海上风电大直径管桩产品。', 'published', NULL, FALSE, 100, 1, '2026-11-26T11:22:13Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-71d58f5c231e297b', '100001', 'news-category-finance-flash', 'em-202611263940753128-30ade52aa5', '亚洲汽油裂解价差转为负值 跌至2020年4月以来最低水平', '因供应充足，亚洲汽油裂解价差转为负值，跌至2020年4月以来最低水平。', 'published', NULL, FALSE, 100, 1, '2026-11-26T11:21:43Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-bc547c3b5f59b01c', '100001', 'news-category-finance-flash', 'em-202611263940746774-e1b530d0ca', '塞尔维亚将于12月27日提前举行总统选举', '塞尔维亚国民议会议长26日宣布，塞尔维亚将于12月27日提前举行总统选举。', 'published', NULL, FALSE, 100, 1, '2026-11-26T11:18:10Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-f5056591f60bc8dc', '100001', 'news-category-finance-flash', 'em-202611263940745538-fe84db4541', '东信和平与中国信通院共建eSIM测试验证平台', '据东信和平消息，近日，东信和平与中国信息通信研究院联合共建的SM-DP+测试验证平台正式上线（SM-DP+，英文全称SubscriptionManagerDataPreparation+，中文译名“订阅管理数据准备+”，是eSIM远程配置体系中负责配置文件生成、安全加密与远程下发的核心平台）。', 'published', NULL, FALSE, 100, 1, '2026-11-26T11:12:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-efbce6bf97663756', '100001', 'news-category-finance-flash', 'em-202611263940745396-e84cb1585f', '惠誉维持2027年英国电力和燃气网络行业“中性”展望 将水务行业展望调整为“恶化”', '惠誉维持2027年英国电力和燃气网络行业“中性”展望，将水务行业展望调整为“恶化”。', 'published', NULL, FALSE, 100, 1, '2026-11-26T11:11:54Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-453b4dbb97321f81', '100001', 'news-category-finance-flash', 'em-202611263940741843-72a6281efc', '花旗：AI设计药物疗效更佳的临床证据料2030年代出现 首选药明生物及英矽智能', '花旗发布研报称，长期而言，人工智能发现的药物具备主导治疗创新的革命性潜力，但证明AI设计分子疗效更佳的临床证据，预计要到2030年代才会出现。个股方面，该行首选药明生物及英矽智能：给予药明生物“买入”评级，目标价62港元；给予英矽智能“买入/高风险”评级，目标价85港元。', 'published', NULL, FALSE, 100, 1, '2026-11-26T11:10:08Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-7d8fd6ecc22e7c4a', '100001', 'news-category-finance-flash', 'em-202611263940741344-8e4f7fb3b1', '天齐锂业：拟4亿至8亿元回购A股股份用于股权激励或员工持股计划', '11月26日，天齐锂业(002466.SZ)公告称，公司拟使用自有资金或自筹资金以集中竞价方式回购A股股份，回购资金总额不低于4亿元且不超过8亿元，回购价格不超过53.08元/股。按回购金额上限测算，预计回购股份数量约1507.16万股，占公司总股本的0.88%；按下限测算，预计回购约753.58万股，占总股本的0.44%。回购股份将用于股权激励或员工持股计划，实施期限为自董事会审议通过之日起12个月内。', 'published', NULL, FALSE, 100, 1, '2026-11-26T11:05:16Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-25d5d6dec604682f', '100001', 'news-category-finance-flash', 'em-202611263940739387-d865a2c3b1', '欧佩克+考虑将当前配额延续至1月份', '欧佩克+考虑将当前配额延续至1月份。', 'published', NULL, FALSE, 100, 1, '2026-11-26T11:02:51Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-8bba87bc9523f752', '100001', 'news-category-finance-flash', 'em-202611263940738316-081cce5412', '华达科技：1-10月获得43个项目定点 预计生命周期总销售金额107.08亿元', '华达科技(603358.SH)公告称，2026年1月到10月，公司获得国内11家客户的23个车身零部件项目定点，预计生命周期3-8年，总销售金额12.82亿元；子公司江苏恒义获得6家客户的20个电池箱托盘等项目定点，预计生命周期2-4年，总销售金额94.26亿元。上述项目合计43个定点，总销售金额107.08亿元，部分项目自2026年一季度起陆续量产。', 'published', NULL, FALSE, 100, 1, '2026-11-26T10:59:01Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-53849ce509a161cf', '100001', 'news-category-finance-flash', 'em-202611263940737949-dd1c8808af', '中鼎股份：拟1亿元至2亿元回购公司股份', '中鼎股份(000887.SZ)公告称，公司拟使用自有或自筹资金以集中竞价方式回购公司已发行A股股票，回购资金总额不低于1亿元且不超过2亿元，回购价格不超过25元/股。', 'published', NULL, FALSE, 100, 1, '2026-11-26T10:56:19Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-44d2c8bc83d7f2b5', '100001', 'news-category-finance-flash', 'em-202611263940737390-f3f2ae8f5e', '镇洋发展：因换股吸收合并事项 公司股票12月4日起连续停牌直至终止上市', '镇洋发展(603213.SH)公告称，因浙江沪杭甬换股吸收合并镇洋发展暨关联交易事项，公司A股股票及可转债将于2026年12月4日开市时起连续停牌。其中，A股股票停牌直至终止上市，不再复牌，2026年12月3日为最后一个交易日；可转债及转股停牌直至浙江沪杭甬上市同日复牌并实施转股。', 'published', NULL, FALSE, 100, 1, '2026-11-26T10:54:17Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-52089cd996b57591', '100001', 'news-category-finance-flash', 'em-202611263940737572-7490f1b43c', '*ST春天：撤销退市风险警示及其他风险警示 11月30日起证券简称变更为“青海春天”', '11月26日，*ST春天(600381.SH)公告称，公司撤销退市风险警示及其他风险警示，股票将于2026年11月27日停牌一天，11月30日起复牌，证券简称由“*ST春天”变更为“青海春天”，股票代码不变。', 'published', NULL, FALSE, 100, 1, '2026-11-26T10:53:14Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-deee298f764f1f06', '100001', 'news-category-finance-flash', 'em-202611263940735260-b93ff96898', '通富微电：董事长提议回购1.5亿至3亿元股份', '通富微电(002156.SZ)公告称，公司董事长石磊提议回购公司股份，回购资金总额不低于1.5亿元且不超过3亿元，回购股份将用于股权激励或员工持股计划。', 'published', NULL, FALSE, 100, 1, '2026-11-26T10:51:13Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
    ('news-item-b4213935dd3f571f', '100001', 'news-category-finance-flash', 'em-202611263940735385-254fcb9080', '国家数据局：人工智能企业不得侵害他人隐私、商业秘密、著作权等合法权益', '国家数据局向社会公开征求《关于完善数据规则赋能人工智能创新发展的若干意见》草案的意见。意见稿提出，建立人工智能企业输出的风险防控机制。人工智能企业作为技术提供方，应主动采取合理必要措施，不得生成危害国家安全、社会公共利益等法律、行政法规禁止的内容，不得侵害他人隐私、商业秘密、著作权等合法权益，不得有悖于主流价值导向，建立应急处置机制、用户投诉反馈渠道并及时处置。', 'published', NULL, FALSE, 100, 1, '2026-11-26T10:50:24Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z')
